import * as THREE from 'three';

function rng(seed = 1) {
  let t = seed >>> 0;
  return () => {
    t += 0x6d2b79f5;
    let r = Math.imul(t ^ (t >>> 15), 1 | t);
    r ^= r + Math.imul(r ^ (r >>> 7), 61 | r);
    return ((r ^ (r >>> 14)) >>> 0) / 4294967296;
  };
}

function canvas(size = 512, h = size) {
  const c = document.createElement('canvas');
  c.width = size;
  c.height = h;
  return [c, c.getContext('2d')];
}

function speckle(ctx, w, h, count, rand, colors, min = 0.4, max = 1.6) {
  for (let i = 0; i < count; i++) {
    ctx.globalAlpha = min + rand() * (max - min);
    ctx.fillStyle = colors[(rand() * colors.length) | 0];
    const s = 0.4 + rand() * 2.2;
    ctx.fillRect(rand() * w, rand() * h, s, s);
  }
  ctx.globalAlpha = 1;
}

function finish(canvas, { repeat = 1, srgb = true } = {}) {
  const tex = new THREE.CanvasTexture(canvas);
  tex.wrapS = tex.wrapT = THREE.RepeatWrapping;
  tex.repeat.set(repeat, repeat);
  tex.anisotropy = 8;
  if (srgb) tex.colorSpace = THREE.SRGBColorSpace;
  tex.needsUpdate = true;
  return tex;
}

export function asphaltTexture() {
  const [c, ctx] = canvas(512);
  const rand = rng(17);
  ctx.fillStyle = '#171b1e';
  ctx.fillRect(0, 0, 512, 512);
  const img = ctx.getImageData(0, 0, 512, 512);
  for (let i = 0; i < img.data.length; i += 4) {
    const n = (rand() - 0.5) * 34;
    img.data[i] = Math.max(5, 23 + n);
    img.data[i + 1] = Math.max(5, 27 + n);
    img.data[i + 2] = Math.max(5, 31 + n);
    img.data[i + 3] = 255;
  }
  ctx.putImageData(img, 0, 0);
  speckle(ctx, 512, 512, 9000, rand, ['#2f3539', '#0c1012', '#3b4245', '#20262a'], 0.18, 0.6);
  for (let i = 0; i < 18; i++) {
    ctx.strokeStyle = `rgba(5,8,9,${0.3 + rand() * 0.4})`;
    ctx.lineWidth = 1 + rand() * 2;
    ctx.beginPath();
    let x = rand() * 512;
    let y = rand() * 512;
    ctx.moveTo(x, y);
    for (let j = 0; j < 6; j++) {
      x += (rand() - 0.5) * 64;
      y += rand() * 32;
      ctx.lineTo(x, y);
    }
    ctx.stroke();
  }
  for (let i = 0; i < 14; i++) {
    ctx.fillStyle = `rgba(117, 132, 136, ${0.02 + rand() * 0.05})`;
    ctx.beginPath();
    ctx.ellipse(rand() * 512, rand() * 512, 25 + rand() * 80, 8 + rand() * 30, rand() * Math.PI, 0, Math.PI * 2);
    ctx.fill();
  }
  return finish(c, { repeat: 7 });
}

export function concreteTexture() {
  const [c, ctx] = canvas(512);
  const rand = rng(83);
  ctx.fillStyle = '#4b5051';
  ctx.fillRect(0, 0, 512, 512);
  const img = ctx.getImageData(0, 0, 512, 512);
  for (let i = 0; i < img.data.length; i += 4) {
    const n = (rand() - 0.5) * 24;
    img.data[i] = 73 + n;
    img.data[i + 1] = 78 + n;
    img.data[i + 2] = 79 + n;
    img.data[i + 3] = 255;
  }
  ctx.putImageData(img, 0, 0);
  speckle(ctx, 512, 512, 5000, rand, ['#5f6564', '#363b3d', '#6c716f'], 0.1, 0.5);
  for (let i = 0; i < 10; i++) {
    const x = rand() * 512;
    const g = ctx.createLinearGradient(0, 0, 0, 512);
    g.addColorStop(0, 'rgba(8,12,13,0)');
    g.addColorStop(0.5, `rgba(8,12,13,${0.14 + rand() * 0.18})`);
    g.addColorStop(1, 'rgba(8,12,13,0)');
    ctx.fillStyle = g;
    ctx.fillRect(x, 0, 4 + rand() * 20, 512);
  }
  ctx.strokeStyle = 'rgba(25,30,31,0.6)';
  ctx.lineWidth = 2;
  ctx.strokeRect(1, 1, 510, 510);
  ctx.strokeStyle = 'rgba(116,125,124,0.2)';
  ctx.strokeRect(5, 5, 502, 502);
  return finish(c, { repeat: 3 });
}

export function metalTexture(base = '#22282c', seed = 3) {
  const [c, ctx] = canvas(512);
  const rand = rng(seed);
  ctx.fillStyle = base;
  ctx.fillRect(0, 0, 512, 512);
  for (let i = 0; i < 700; i++) {
    ctx.strokeStyle = `rgba(210,225,230,${rand() * 0.045})`;
    ctx.lineWidth = 0.5 + rand();
    const y = rand() * 512;
    ctx.beginPath();
    ctx.moveTo(rand() * 250, y);
    ctx.lineTo(rand() * 512, y + (rand() - 0.5) * 2);
    ctx.stroke();
  }
  for (let i = 0; i < 35; i++) {
    ctx.strokeStyle = `rgba(220,238,242,${0.06 + rand() * 0.18})`;
    ctx.lineWidth = 0.6;
    ctx.beginPath();
    const x = rand() * 512;
    const y = rand() * 512;
    ctx.moveTo(x, y);
    ctx.lineTo(x + (rand() - 0.5) * 80, y + (rand() - 0.5) * 80);
    ctx.stroke();
  }
  for (let i = 0; i < 9; i++) {
    const x = rand() * 512;
    const y = rand() * 512;
    const g = ctx.createRadialGradient(x, y, 1, x, y, 12 + rand() * 32);
    g.addColorStop(0, 'rgba(10,12,13,0.4)');
    g.addColorStop(1, 'rgba(10,12,13,0)');
    ctx.fillStyle = g;
    ctx.fillRect(x - 50, y - 50, 100, 100);
  }
  // rivets
  for (let i = 0; i < 28; i++) {
    const x = 20 + rand() * 472;
    const y = 20 + rand() * 472;
    ctx.fillStyle = 'rgba(8,10,11,0.65)';
    ctx.beginPath(); ctx.arc(x, y, 2.2, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = 'rgba(130,146,150,0.22)';
    ctx.beginPath(); ctx.arc(x - 0.7, y - 0.7, 1.2, 0, Math.PI * 2); ctx.fill();
  }
  return finish(c, { repeat: 2 });
}

export function containerTexture(color = '#3d4b4b', accent = '#9a4c24', seed = 10) {
  const [c, ctx] = canvas(512);
  const rand = rng(seed);
  ctx.fillStyle = color;
  ctx.fillRect(0, 0, 512, 512);
  const grd = ctx.createLinearGradient(0, 0, 0, 512);
  grd.addColorStop(0, 'rgba(255,255,255,0.09)');
  grd.addColorStop(0.55, 'rgba(0,0,0,0)');
  grd.addColorStop(1, 'rgba(0,0,0,0.25)');
  ctx.fillStyle = grd;
  ctx.fillRect(0, 0, 512, 512);
  for (let x = 0; x < 512; x += 32) {
    ctx.fillStyle = 'rgba(0,0,0,0.17)';
    ctx.fillRect(x, 0, 3, 512);
    ctx.fillStyle = 'rgba(255,255,255,0.06)';
    ctx.fillRect(x + 3, 0, 2, 512);
  }
  for (let i = 0; i < 950; i++) {
    ctx.globalAlpha = rand() * 0.5;
    ctx.fillStyle = rand() > 0.55 ? '#0b0e0f' : accent;
    ctx.fillRect(rand() * 512, rand() * 512, 1 + rand() * 5, 1 + rand() * 2);
  }
  ctx.globalAlpha = 1;
  for (let i = 0; i < 8; i++) {
    const x = rand() * 512;
    const y = rand() * 512;
    const r = 2 + rand() * 15;
    const g = ctx.createRadialGradient(x, y, 1, x, y, r);
    g.addColorStop(0, `rgba(145,68,25,${0.15 + rand() * 0.2})`);
    g.addColorStop(1, 'rgba(145,68,25,0)');
    ctx.fillStyle = g;
    ctx.fillRect(x - r, y - r, r * 2, r * 2);
  }
  ctx.fillStyle = 'rgba(8,10,11,0.7)';
  ctx.font = 'bold 20px Arial';
  ctx.fillText('MERIDIAN PORT AUTHORITY', 24, 52);
  ctx.font = '13px Arial';
  ctx.fillStyle = 'rgba(8,10,11,0.54)';
  ctx.fillText('MSKU 407 221 7  //  MAX GROSS 30,480 KG', 25, 75);
  return finish(c, { repeat: 1 });
}

export function hazardTexture() {
  const [c, ctx] = canvas(512, 128);
  ctx.fillStyle = '#151819';
  ctx.fillRect(0, 0, 512, 128);
  ctx.save();
  ctx.translate(0, 0);
  for (let x = -128; x < 640; x += 74) {
    ctx.fillStyle = '#c27c19';
    ctx.beginPath();
    ctx.moveTo(x, 128); ctx.lineTo(x + 37, 128); ctx.lineTo(x + 94, 0); ctx.lineTo(x + 57, 0);
    ctx.closePath(); ctx.fill();
  }
  ctx.restore();
  const rand = rng(31);
  for (let i = 0; i < 500; i++) {
    ctx.globalAlpha = rand() * 0.4;
    ctx.fillStyle = '#0a0c0d';
    ctx.fillRect(rand() * 512, rand() * 128, 2 + rand() * 4, 1 + rand() * 3);
  }
  return finish(c, { repeat: 1 });
}

export function signTexture(main, sub = '', color = '#ff8a2a', seed = 4) {
  const [c, ctx] = canvas(768, 256);
  const rand = rng(seed);
  ctx.fillStyle = '#080d10';
  ctx.fillRect(0, 0, 768, 256);
  ctx.fillStyle = 'rgba(255,255,255,0.025)';
  for (let i = 0; i < 20; i++) ctx.fillRect(0, i * 13, 768, 1);
  ctx.strokeStyle = color;
  ctx.lineWidth = 5;
  ctx.strokeRect(12, 12, 744, 232);
  ctx.strokeStyle = 'rgba(255,255,255,0.16)';
  ctx.lineWidth = 1;
  ctx.strokeRect(24, 24, 720, 208);
  ctx.fillStyle = color;
  ctx.font = 'bold 105px Arial';
  ctx.textBaseline = 'middle';
  ctx.fillText(main, 48, 110);
  ctx.fillStyle = 'rgba(220,240,245,0.72)';
  ctx.font = '28px Arial';
  ctx.fillText(sub, 51, 190);
  for (let i = 0; i < 40; i++) {
    ctx.globalAlpha = rand() * 0.18;
    ctx.fillStyle = '#000';
    ctx.fillRect(rand() * 768, rand() * 256, 1 + rand() * 14, 1 + rand() * 3);
  }
  return finish(c, { repeat: 1 });
}

export function groundNumberTexture(text = '07', color = '#b88425') {
  const [c, ctx] = canvas(512, 512);
  ctx.clearRect(0, 0, 512, 512);
  ctx.strokeStyle = color;
  ctx.globalAlpha = 0.42;
  ctx.lineWidth = 10;
  ctx.beginPath(); ctx.arc(256, 256, 190, 0, Math.PI * 2); ctx.stroke();
  ctx.globalAlpha = 0.24;
  ctx.lineWidth = 2;
  ctx.beginPath(); ctx.arc(256, 256, 158, 0, Math.PI * 2); ctx.stroke();
  ctx.globalAlpha = 0.5;
  ctx.fillStyle = color;
  ctx.font = 'bold 240px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(text, 256, 272);
  ctx.font = 'bold 30px Arial';
  ctx.fillText('SECTOR', 256, 70);
  ctx.fillText('AUTHORIZED VEHICLES ONLY', 256, 448);
  return finish(c, { repeat: 1 });
}

export function puddleTexture() {
  const [c, ctx] = canvas(256);
  const rand = rng(52);
  ctx.clearRect(0, 0, 256, 256);
  for (let i = 0; i < 7; i++) {
    const x = 40 + rand() * 176;
    const y = 40 + rand() * 176;
    const r = 30 + rand() * 55;
    const g = ctx.createRadialGradient(x, y, 2, x, y, r);
    g.addColorStop(0, 'rgba(210,245,255,0.85)');
    g.addColorStop(0.55, 'rgba(150,220,240,0.45)');
    g.addColorStop(1, 'rgba(120,200,230,0)');
    ctx.fillStyle = g;
    ctx.beginPath(); ctx.ellipse(x, y, r, r * (0.4 + rand() * 0.35), rand() * Math.PI, 0, Math.PI * 2); ctx.fill();
  }
  return finish(c, { repeat: 1 });
}

export function glowTexture(inner = 'rgba(255,255,255,1)', outer = 'rgba(255,255,255,0)', size = 128) {
  const [c, ctx] = canvas(size);
  const g = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
  g.addColorStop(0, inner);
  g.addColorStop(0.28, inner);
  g.addColorStop(1, outer);
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, size, size);
  return finish(c, { repeat: 1 });
}

export function smokeTexture() {
  const size = 128;
  const [c, ctx] = canvas(size);
  const rand = rng(9);
  const g = ctx.createRadialGradient(64, 64, 6, 64, 64, 62);
  g.addColorStop(0, 'rgba(170,190,198,0.8)');
  g.addColorStop(0.45, 'rgba(120,140,148,0.42)');
  g.addColorStop(1, 'rgba(80,95,102,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, size, size);
  for (let i = 0; i < 26; i++) {
    ctx.fillStyle = `rgba(255,255,255,${rand() * 0.05})`;
    ctx.beginPath(); ctx.arc(64 + (rand() - 0.5) * 40, 64 + (rand() - 0.5) * 40, 4 + rand() * 15, 0, Math.PI * 2); ctx.fill();
  }
  return finish(c, { repeat: 1 });
}

export function bulletHoleTexture() {
  const [c, ctx] = canvas(64);
  const g = ctx.createRadialGradient(32, 32, 1, 32, 32, 30);
  g.addColorStop(0, 'rgba(0,0,0,0.98)');
  g.addColorStop(0.24, 'rgba(5,6,7,0.96)');
  g.addColorStop(0.5, 'rgba(40,42,42,0.66)');
  g.addColorStop(0.72, 'rgba(108,102,91,0.22)');
  g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 64, 64);
  return finish(c, { repeat: 1 });
}

export function skyTexture() {
  const [c, ctx] = canvas(1024, 512);
  const g = ctx.createLinearGradient(0, 0, 0, 512);
  g.addColorStop(0, '#010307');
  g.addColorStop(0.38, '#06101b');
  g.addColorStop(0.68, '#0d1b29');
  g.addColorStop(0.82, '#182b38');
  g.addColorStop(1, '#24323a');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 1024, 512);
  const rand = rng(76);
  for (let i = 0; i < 420; i++) {
    const x = rand() * 1024;
    const y = rand() * 330;
    const a = rand() * 0.55;
    ctx.fillStyle = `rgba(196,225,245,${a})`;
    const s = rand() > 0.94 ? 2 : 1;
    ctx.fillRect(x, y, s, s);
  }
  for (let i = 0; i < 24; i++) {
    const x = rand() * 1024;
    const y = 80 + rand() * 280;
    const r = 50 + rand() * 180;
    const cg = ctx.createRadialGradient(x, y, 1, x, y, r);
    cg.addColorStop(0, 'rgba(40,59,72,0.10)');
    cg.addColorStop(1, 'rgba(20,30,40,0)');
    ctx.fillStyle = cg;
    ctx.fillRect(x - r, y - r, r * 2, r * 2);
  }
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.wrapS = THREE.RepeatWrapping;
  tex.needsUpdate = true;
  return tex;
}

export function rainTexture() {
  const [c, ctx] = canvas(64, 128);
  const g = ctx.createLinearGradient(0, 0, 0, 128);
  g.addColorStop(0, 'rgba(190,228,245,0)');
  g.addColorStop(0.55, 'rgba(190,228,245,0.55)');
  g.addColorStop(1, 'rgba(220,245,255,0.9)');
  ctx.fillStyle = g;
  ctx.fillRect(29, 0, 5, 128);
  ctx.filter = 'blur(2px)';
  ctx.fillRect(28, 0, 7, 128);
  return finish(c, { repeat: 1 });
}

export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.volume = 0.7;
    this.noise = null;
    this.ambient = [];
    this.heartbeat = 0;
  }

  init() {
    if (this.ctx) { this.resume(); return; }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    const comp = this.ctx.createDynamicsCompressor();
    comp.threshold.value = -16;
    comp.knee.value = 18;
    comp.ratio.value = 5;
    comp.attack.value = 0.003;
    comp.release.value = 0.25;
    this.master = this.ctx.createGain();
    this.master.gain.value = this.volume;
    this.master.connect(comp);
    comp.connect(this.ctx.destination);
    this.noise = this.makeNoise(2.2);
    this.startAmbient();
  }

  resume() {
    if (this.ctx?.state === 'suspended') this.ctx.resume();
  }

  setVolume(v) {
    this.volume = Math.max(0, Math.min(1, v));
    if (this.master) this.master.gain.setTargetAtTime(this.volume, this.ctx.currentTime, 0.05);
  }

  makeNoise(seconds) {
    const len = Math.floor(this.ctx.sampleRate * seconds);
    const buffer = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = buffer.getChannelData(0);
    let last = 0;
    for (let i = 0; i < len; i++) {
      const white = Math.random() * 2 - 1;
      last = last * 0.72 + white * 0.28;
      data[i] = last * 1.9;
    }
    return buffer;
  }

  noiseSource(playbackRate = 1) {
    const src = this.ctx.createBufferSource();
    src.buffer = this.noise;
    src.loop = true;
    src.playbackRate.value = playbackRate;
    return src;
  }

  startAmbient() {
    const ctx = this.ctx;
    const bus = ctx.createGain();
    bus.gain.value = 0.12;
    bus.connect(this.master);

    const rain = this.noiseSource(1.35);
    const rainFilter = ctx.createBiquadFilter();
    rainFilter.type = 'bandpass';
    rainFilter.frequency.value = 1800;
    rainFilter.Q.value = 0.35;
    const rainGain = ctx.createGain();
    rainGain.gain.value = 0.42;
    rain.connect(rainFilter);
    rainFilter.connect(rainGain);
    rainGain.connect(bus);
    rain.start();

    const wind = this.noiseSource(0.45);
    const windFilter = ctx.createBiquadFilter();
    windFilter.type = 'lowpass';
    windFilter.frequency.value = 190;
    const windGain = ctx.createGain();
    windGain.gain.value = 0.3;
    wind.connect(windFilter);
    windFilter.connect(windGain);
    windGain.connect(bus);
    wind.start();

    const humGain = ctx.createGain();
    humGain.gain.value = 0.035;
    humGain.connect(this.master);
    [45, 67.5, 90.5].forEach((f, i) => {
      const osc = ctx.createOscillator();
      osc.type = i === 2 ? 'triangle' : 'sine';
      osc.frequency.value = f;
      const g = ctx.createGain();
      g.gain.value = 0.3 / (i + 1);
      osc.connect(g);
      g.connect(humGain);
      osc.start();
      this.ambient.push(osc);
    });

    const lfo = ctx.createOscillator();
    const lfoGain = ctx.createGain();
    lfo.frequency.value = 0.07;
    lfoGain.gain.value = 0.018;
    lfo.connect(lfoGain);
    lfoGain.connect(humGain.gain);
    lfo.start();
    this.ambient.push(lfo);
    this.ambient.push(rain, wind);
  }

  env(gain, t, peak, attack, decay) {
    gain.gain.setValueAtTime(0.0001, t);
    gain.gain.exponentialRampToValueAtTime(Math.max(0.0002, peak), t + attack);
    gain.gain.exponentialRampToValueAtTime(0.0001, t + attack + decay);
  }

  burst({ rate = 1, freq = 1000, q = 0.7, peak = 0.5, attack = 0.002, decay = 0.12, type = 'lowpass', delay = 0, pan = 0 }) {
    if (!this.ctx) return;
    const t = this.ctx.currentTime + delay;
    const src = this.noiseSource(rate);
    const filter = this.ctx.createBiquadFilter();
    filter.type = type;
    filter.frequency.value = freq;
    filter.Q.value = q;
    const gain = this.ctx.createGain();
    let node = gain;
    if (pan) {
      const p = this.ctx.createStereoPanner();
      p.pan.value = pan;
      gain.connect(p);
      node = p;
    }
    src.connect(filter);
    filter.connect(gain);
    node.connect(this.master);
    this.env(gain, t, peak, attack, decay);
    src.start(t);
    src.stop(t + attack + decay + 0.05);
  }

  tone({ freq = 440, end = null, type = 'sine', peak = 0.15, attack = 0.005, decay = 0.15, delay = 0, pan = 0 }) {
    if (!this.ctx) return;
    const t = this.ctx.currentTime + delay;
    const osc = this.ctx.createOscillator();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    if (end) osc.frequency.exponentialRampToValueAtTime(Math.max(10, end), t + attack + decay);
    const gain = this.ctx.createGain();
    let node = gain;
    if (pan) {
      const p = this.ctx.createStereoPanner();
      p.pan.value = pan;
      gain.connect(p);
      node = p;
    }
    osc.connect(gain);
    node.connect(this.master);
    this.env(gain, t, peak, attack, decay);
    osc.start(t);
    osc.stop(t + attack + decay + 0.05);
  }

  shot() {
    if (!this.ctx) return;
    this.burst({ rate: 1.8, freq: 4600, type: 'highpass', peak: 0.5, decay: 0.045 });
    this.burst({ rate: 1, freq: 820, type: 'lowpass', peak: 0.55, decay: 0.14 });
    this.burst({ rate: 0.7, freq: 300, type: 'lowpass', peak: 0.6, decay: 0.28, delay: 0.015 });
    this.tone({ freq: 145, end: 38, type: 'sine', peak: 0.55, decay: 0.17 });
    this.tone({ freq: 78, end: 32, type: 'triangle', peak: 0.25, decay: 0.26 });
  }

  enemyShot(distance = 10, pan = 0) {
    const v = Math.max(0.05, 1 - distance / 55);
    this.burst({ rate: 1.2, freq: 2800, type: 'highpass', peak: 0.22 * v, decay: 0.05, pan });
    this.burst({ rate: 0.8, freq: 420, peak: 0.3 * v, decay: 0.2, delay: 0.01, pan });
    this.tone({ freq: 110, end: 35, peak: 0.17 * v, decay: 0.2, pan });
  }

  hit(head = false) {
    if (!this.ctx) return;
    this.tone({ freq: head ? 2300 : 1500, end: head ? 1400 : 1100, type: 'square', peak: 0.06, decay: 0.035 });
    if (head) {
      this.tone({ freq: 3100, peak: 0.045, decay: 0.1, delay: 0.015 });
      this.burst({ freq: 6000, type: 'highpass', peak: 0.07, decay: 0.05 });
    }
  }

  empty() {
    this.burst({ freq: 2800, type: 'highpass', peak: 0.16, decay: 0.025 });
    this.tone({ freq: 900, end: 450, type: 'square', peak: 0.035, decay: 0.04 });
  }

  reload(duration = 1.8) {
    if (!this.ctx) return;
    const t = 0;
    this.burst({ freq: 2200, type: 'bandpass', q: 1.2, peak: 0.14, decay: 0.045, delay: t });
    this.burst({ freq: 1200, q: 2, type: 'bandpass', peak: 0.18, decay: 0.07, delay: duration * 0.36 });
    this.tone({ freq: 310, end: 190, type: 'square', peak: 0.04, decay: 0.06, delay: duration * 0.55 });
    this.burst({ freq: 1800, type: 'bandpass', q: 1.4, peak: 0.2, decay: 0.08, delay: duration * 0.8 });
    this.tone({ freq: 520, end: 300, type: 'square', peak: 0.05, decay: 0.05, delay: duration * 0.84 });
  }

  damage() {
    if (!this.ctx) return;
    this.tone({ freq: 82, end: 34, type: 'sine', peak: 0.36, decay: 0.26 });
    this.burst({ rate: 0.5, freq: 520, type: 'lowpass', peak: 0.26, decay: 0.18 });
    this.tone({ freq: 1900, end: 700, type: 'sawtooth', peak: 0.035, decay: 0.17, delay: 0.03 });
  }

  enemyDown() {
    this.burst({ rate: 0.6, freq: 700, type: 'lowpass', peak: 0.12, decay: 0.2 });
  }

  waveStart(wave = 1) {
    if (!this.ctx) return;
    this.tone({ freq: 190, end: 320, type: 'sawtooth', peak: 0.08, attack: 0.02, decay: 0.4 });
    this.tone({ freq: 95, end: 160, type: 'square', peak: 0.06, attack: 0.02, decay: 0.5 });
    this.tone({ freq: 1120, peak: 0.05, decay: 0.08, delay: 0.12 });
    this.tone({ freq: 1120, peak: 0.05, decay: 0.08, delay: 0.24 });
    if (wave >= 5) {
      this.tone({ freq: 240, end: 90, type: 'sawtooth', peak: 0.1, decay: 0.9, delay: 0.4 });
    }
  }

  waveClear() {
    if (!this.ctx) return;
    [523.25, 659.25, 783.99].forEach((f, i) => this.tone({ freq: f, peak: 0.055, decay: 0.45, delay: i * 0.1 }));
  }

  win() {
    if (!this.ctx) return;
    [261.6, 329.6, 392, 523.25, 659.25].forEach((f, i) => this.tone({ freq: f, type: 'triangle', peak: 0.07, decay: 0.8, delay: i * 0.16 }));
  }

  lose() {
    if (!this.ctx) return;
    this.tone({ freq: 180, end: 48, type: 'sawtooth', peak: 0.15, decay: 1.2 });
    this.tone({ freq: 90, end: 30, type: 'sine', peak: 0.2, decay: 1.4 });
  }

  pickup() {
    this.tone({ freq: 740, end: 1180, type: 'sine', peak: 0.07, decay: 0.12 });
    this.tone({ freq: 1480, peak: 0.045, decay: 0.14, delay: 0.06 });
  }

  lowHealthBeat(intensity = 1) {
    if (!this.ctx) return;
    const now = performance.now();
    if (now - this.heartbeat < 720) return;
    this.heartbeat = now;
    this.tone({ freq: 58, end: 34, type: 'sine', peak: 0.11 * intensity, decay: 0.18 });
    this.tone({ freq: 48, end: 28, type: 'sine', peak: 0.07 * intensity, decay: 0.22, delay: 0.2 });
  }
}

export const audio = new AudioEngine();

import * as THREE from 'three';
import { glowTexture, smokeTexture, bulletHoleTexture } from './textures.js';

const _v = new THREE.Vector3();
const _q = new THREE.Quaternion();
const _up = new THREE.Vector3(0, 0, 1);
const _m = new THREE.Matrix4();

export class Effects {
  constructor(scene) {
    this.scene = scene;
    this.glow = glowTexture('rgba(255,235,196,1)', 'rgba(255,120,20,0)');
    this.smokeTex = smokeTexture();
    this.holeTex = bulletHoleTexture();
    this.time = 0;

    this.sprites = [];
    for (let i = 0; i < 42; i++) {
      const mat = new THREE.SpriteMaterial({ map: this.glow, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false });
      const sprite = new THREE.Sprite(mat);
      sprite.visible = false;
      sprite.userData = { life: 0, max: 0, vx: 0, vy: 0, vz: 0, grow: 1, fade: 1, kind: 'glow' };
      scene.add(sprite);
      this.sprites.push(sprite);
    }

    this.smokes = [];
    for (let i = 0; i < 30; i++) {
      const mat = new THREE.SpriteMaterial({ map: this.smokeTex, transparent: true, opacity: 0, depthWrite: false, color: 0x93a7ad });
      const sprite = new THREE.Sprite(mat);
      sprite.visible = false;
      sprite.userData = { life: 0, max: 0, vx: 0, vy: 0, vz: 0, grow: 1 };
      scene.add(sprite);
      this.smokes.push(sprite);
    }

    this.tracers = [];
    for (let i = 0; i < 34; i++) {
      const geo = new THREE.BufferGeometry();
      geo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(6), 3));
      const mat = new THREE.LineBasicMaterial({ color: 0xffd49a, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false });
      const line = new THREE.Line(geo, mat);
      line.frustumCulled = false;
      line.visible = false;
      scene.add(line);
      this.tracers.push({ line, life: 0 });
    }

    const capacity = 900;
    this.capacity = capacity;
    this.pPos = new Float32Array(capacity * 3);
    this.pCol = new Float32Array(capacity * 3);
    this.pVel = new Float32Array(capacity * 3);
    this.pLife = new Float32Array(capacity);
    this.pMax = new Float32Array(capacity);
    this.pGrav = new Float32Array(capacity);
    this.pDrag = new Float32Array(capacity);
    this.pBase = new Float32Array(capacity * 3);
    for (let i = 0; i < capacity; i++) this.pPos[i * 3 + 1] = -999;
    const geo = new THREE.BufferGeometry();
    geo.setAttribute('position', new THREE.BufferAttribute(this.pPos, 3));
    geo.setAttribute('color', new THREE.BufferAttribute(this.pCol, 3));
    const mat = new THREE.PointsMaterial({ size: 0.075, vertexColors: true, transparent: true, opacity: 0.95, depthWrite: false, blending: THREE.AdditiveBlending, sizeAttenuation: true, toneMapped: false });
    this.points = new THREE.Points(geo, mat);
    this.points.frustumCulled = false;
    scene.add(this.points);
    this.pCursor = 0;

    this.decals = [];
    for (let i = 0; i < 70; i++) {
      const mat = new THREE.MeshBasicMaterial({ map: this.holeTex, transparent: true, depthWrite: false, polygonOffset: true, polygonOffsetFactor: -3, polygonOffsetUnits: -3, side: THREE.DoubleSide, toneMapped: false });
      const mesh = new THREE.Mesh(new THREE.PlaneGeometry(0.16, 0.16), mat);
      mesh.visible = false;
      scene.add(mesh);
      this.decals.push(mesh);
    }
    this.decalCursor = 0;

    this.casings = [];
    for (let i = 0; i < 18; i++) {
      const mat = new THREE.MeshStandardMaterial({ color: 0xc59b43, metalness: 1, roughness: 0.3 });
      const mesh = new THREE.Mesh(new THREE.CylinderGeometry(0.011, 0.013, 0.05, 6), mat);
      mesh.visible = false;
      scene.add(mesh);
      this.casings.push({ mesh, life: 0, vy: 0, vx: 0, vz: 0, spin: 0 });
    }
    this.casingCursor = 0;

    this.rings = [];
    for (let i = 0; i < 8; i++) {
      const mat = new THREE.MeshBasicMaterial({ color: 0xffa040, transparent: true, opacity: 0, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false });
      const mesh = new THREE.Mesh(new THREE.RingGeometry(0.5, 0.56, 48), mat);
      mesh.rotation.x = -Math.PI / 2;
      mesh.visible = false;
      scene.add(mesh);
      this.rings.push({ mesh, life: 0, max: 0, grow: 1 });
    }
    this.ringCursor = 0;

    this.flash = new THREE.PointLight(0xffa850, 0, 11, 2);
    scene.add(this.flash);
  }

  particle(x, y, z, vx, vy, vz, life, color, gravity = 9, drag = 0.6, jitter = 0.35) {
    const i = this.pCursor;
    this.pCursor = (this.pCursor + 1) % this.capacity;
    this.pPos[i * 3] = x + (Math.random() - 0.5) * jitter;
    this.pPos[i * 3 + 1] = y + (Math.random() - 0.5) * jitter;
    this.pPos[i * 3 + 2] = z + (Math.random() - 0.5) * jitter;
    this.pVel[i * 3] = vx;
    this.pVel[i * 3 + 1] = vy;
    this.pVel[i * 3 + 2] = vz;
    this.pLife[i] = life;
    this.pMax[i] = life;
    this.pGrav[i] = gravity;
    this.pDrag[i] = drag;
    const c = color.isColor ? color : new THREE.Color(color);
    this.pBase[i * 3] = c.r;
    this.pBase[i * 3 + 1] = c.g;
    this.pBase[i * 3 + 2] = c.b;
    this.pCol[i * 3] = c.r;
    this.pCol[i * 3 + 1] = c.g;
    this.pCol[i * 3 + 2] = c.b;
  }

  spriteAt(pos, scale, life, color = 0xffc070, kind = 'glow') {
    const sprite = this.sprites.find(s => !s.visible);
    if (!sprite) return;
    sprite.visible = true;
    sprite.position.copy(pos);
    sprite.scale.setScalar(scale);
    sprite.material.color.setHex(color);
    sprite.material.opacity = 0.9;
    sprite.userData.life = life;
    sprite.userData.max = life;
    sprite.userData.kind = kind;
    sprite.userData.grow = kind === 'muzzle' ? 1.5 : 1.1;
  }

  smokeAt(pos, scale, life, color = 0x93a7ad, drift = 0.5) {
    const sprite = this.smokes.find(s => !s.visible);
    if (!sprite) return;
    sprite.visible = true;
    sprite.position.copy(pos);
    sprite.scale.setScalar(scale);
    sprite.material.color.setHex(color);
    sprite.material.opacity = 0.0;
    sprite.userData.life = life;
    sprite.userData.max = life;
    sprite.userData.grow = 1.6 + Math.random() * 0.9;
    sprite.userData.vx = (Math.random() - 0.5) * drift;
    sprite.userData.vy = 0.25 + Math.random() * 0.5;
    sprite.userData.vz = (Math.random() - 0.5) * drift;
  }

  tracer(start, end, color = 0xffc985, life = 0.055) {
    const slot = this.tracers.find(t => !t.line.visible) || this.tracers[0];
    const arr = slot.line.geometry.attributes.position.array;
    arr[0] = start.x; arr[1] = start.y; arr[2] = start.z;
    arr[3] = end.x; arr[4] = end.y; arr[5] = end.z;
    slot.line.geometry.attributes.position.needsUpdate = true;
    slot.line.material.color.setHex(color);
    slot.line.material.opacity = 0.95;
    slot.line.visible = true;
    slot.life = life;
    slot.max = life;
  }

  muzzleFlash(pos, dir, scale = 1) {
    this.spriteAt(pos, 0.85 * scale, 0.065, 0xffb35a, 'muzzle');
    this.spriteAt(pos, 0.32 * scale, 0.075, 0xfff0cf, 'muzzle');
    this.flash.position.copy(pos);
    this.flash.intensity = 30 * scale;
    for (let i = 0; i < 5; i++) {
      const spread = 3.2;
      this.particle(pos.x, pos.y, pos.z, dir.x * (2 + Math.random() * 4) + (Math.random() - 0.5) * spread, dir.y * (2 + Math.random() * 4) + (Math.random() - 0.5) * spread, dir.z * (2 + Math.random() * 4) + (Math.random() - 0.5) * spread, 0.1 + Math.random() * 0.1, 0xffb04a, 2, 0.9, 0.05);
    }
  }

  impact(point, normal, kind = 'metal') {
    const nrm = normal.clone().normalize();
    for (let i = 0; i < 11; i++) {
      const speed = 1.5 + Math.random() * 5.5;
      _v.set((Math.random() - 0.5), (Math.random() - 0.5), (Math.random() - 0.5)).normalize().multiplyScalar(speed).addScaledVector(nrm, 2.8);
      const color = kind === 'blood' ? 0xff2f22 : (Math.random() > 0.4 ? 0xffb34d : 0xffe7c0);
      this.particle(point.x, point.y, point.z, _v.x, _v.y, _v.z, 0.18 + Math.random() * 0.36, color, kind === 'blood' ? 14 : 8, 0.8, 0.06);
    }
    if (kind !== 'blood') {
      this.smokeAt(point.clone().addScaledVector(nrm, 0.03), 0.2, 0.55, 0xa8b3b5, 0.25);
      this.spriteAt(point.clone().addScaledVector(nrm, 0.02), 0.18, 0.06, 0xffd9a0);
      this.decal(point, nrm);
    } else {
      this.spriteAt(point, 0.2, 0.12, 0x9c1008);
    }
  }

  decal(point, normal) {
    const mesh = this.decals[this.decalCursor];
    this.decalCursor = (this.decalCursor + 1) % this.decals.length;
    mesh.visible = true;
    mesh.position.copy(point).addScaledVector(normal, 0.012);
    _q.setFromUnitVectors(_up, normal);
    mesh.quaternion.copy(_q);
    const spin = new THREE.Quaternion().setFromAxisAngle(_up, Math.random() * Math.PI * 2);
    mesh.quaternion.multiply(spin);
    const s = 0.7 + Math.random() * 0.55;
    mesh.scale.setScalar(s);
    mesh.material.rotation = Math.random() * Math.PI;
  }

  casing(pos, velocity) {
    const slot = this.casings[this.casingCursor];
    this.casingCursor = (this.casingCursor + 1) % this.casings.length;
    slot.mesh.visible = true;
    slot.mesh.position.copy(pos);
    slot.mesh.rotation.set(Math.random() * 3, Math.random() * 3, Math.random() * 3);
    slot.vx = velocity.x;
    slot.vy = velocity.y;
    slot.vz = velocity.z;
    slot.life = 1.6;
    slot.spin = 8 + Math.random() * 12;
  }

  deathBurst(pos, color = 0xff3a2e, scale = 1) {
    for (let i = 0; i < 30 * scale; i++) {
      const speed = (1 + Math.random() * 4) * scale;
      _v.set((Math.random() - 0.5), Math.random() * 1.3, (Math.random() - 0.5)).normalize().multiplyScalar(speed);
      this.particle(pos.x, pos.y + 0.8 + Math.random(), pos.z, _v.x, _v.y, _v.z, 0.4 + Math.random() * 0.7, i % 4 === 0 ? 0xffb066 : color, 5, 0.6);
    }
    this.smokeAt(pos.clone().setY(pos.y + 0.7), 0.75 * scale, 1.5, 0x7a6260, 0.8);
    this.spriteAt(pos.clone().setY(pos.y + 1), 0.85 * scale, 0.22, 0xff5733);
    this.ring(pos, 0xff4c2a, 0.55 * scale, 1.4);
  }

  spawnRing(pos, color = 0xff4c2a, scale = 1) {
    this.ring(pos, color, 0.7 * scale, 1.8);
    for (let i = 0; i < 26; i++) {
      const a = Math.random() * Math.PI * 2;
      const r = 0.3 + Math.random() * 0.5;
      this.particle(pos.x + Math.cos(a) * r, pos.y + Math.random() * 1.7, pos.z + Math.sin(a) * r, 0, 1.4 + Math.random() * 2.5, 0, 0.3 + Math.random() * 0.6, color, 1.5, 0.3);
    }
  }

  ring(pos, color, scale, grow) {
    const slot = this.rings[this.ringCursor];
    this.ringCursor = (this.ringCursor + 1) % this.rings.length;
    slot.mesh.visible = true;
    slot.mesh.position.copy(pos).setY(0.045);
    slot.mesh.scale.setScalar(scale);
    slot.mesh.material.color.setHex(color);
    slot.mesh.material.opacity = 0.85;
    slot.life = 0.6;
    slot.max = 0.6;
    slot.grow = grow;
  }

  explode(pos, color = 0xff7b35, scale = 1) {
    this.spriteAt(pos, 2.6 * scale, 0.18, 0xffc176);
    this.spriteAt(pos, 1.1 * scale, 0.25, 0xfff4da);
    this.flash.position.copy(pos);
    this.flash.intensity = 110 * scale;
    for (let i = 0; i < 55 * scale; i++) {
      const speed = (2 + Math.random() * 7) * scale;
      _v.set((Math.random() - 0.5) * 2, Math.random() * 1.6, (Math.random() - 0.5) * 2).normalize().multiplyScalar(speed);
      this.particle(pos.x, pos.y, pos.z, _v.x, _v.y, _v.z, 0.4 + Math.random() * 0.8, i % 3 === 0 ? 0xffdfa0 : color, 7, 0.5);
    }
    for (let i = 0; i < 5; i++) {
      this.smokeAt(pos.clone().add(new THREE.Vector3((Math.random() - 0.5) * 1.5, Math.random() * 1.5, (Math.random() - 0.5) * 1.5)), 1.2 * scale, 1.4 + Math.random(), 0x5b5550, 1.3);
    }
    this.ring(pos, color, 1.1 * scale, 3.5);
  }

  update(dt) {
    this.time += dt;
    for (const sprite of this.sprites) {
      if (!sprite.visible) continue;
      const u = sprite.userData;
      u.life -= dt;
      if (u.life <= 0) { sprite.visible = false; sprite.material.opacity = 0; continue; }
      const t = u.life / u.max;
      sprite.material.opacity = (u.kind === 'muzzle' ? 1 : 0.7) * Math.min(1, t * 2.2);
      sprite.scale.multiplyScalar(1 + (u.grow - 1) * dt * 9);
    }
    for (const sprite of this.smokes) {
      if (!sprite.visible) continue;
      const u = sprite.userData;
      u.life -= dt;
      if (u.life <= 0) { sprite.visible = false; sprite.material.opacity = 0; continue; }
      const t = u.life / u.max;
      sprite.position.x += u.vx * dt;
      sprite.position.y += u.vy * dt;
      sprite.position.z += u.vz * dt;
      sprite.scale.multiplyScalar(1 + (u.grow - 1) * dt * 4);
      sprite.material.opacity = Math.sin(Math.min(1, t * 2.3) * Math.PI * 0.5) * 0.24 * t;
    }
    for (const slot of this.tracers) {
      if (!slot.line.visible) continue;
      slot.life -= dt;
      if (slot.life <= 0) { slot.line.visible = false; continue; }
      slot.line.material.opacity = Math.max(0, slot.life / slot.max) * 0.9;
    }
    for (let i = 0; i < this.capacity; i++) {
      if (this.pLife[i] <= 0) continue;
      this.pLife[i] -= dt;
      if (this.pLife[i] <= 0) {
        this.pPos[i * 3 + 1] = -999;
        this.pCol[i * 3] = this.pCol[i * 3 + 1] = this.pCol[i * 3 + 2] = 0;
        continue;
      }
      const drag = Math.max(0, 1 - this.pDrag[i] * dt);
      this.pVel[i * 3] *= drag;
      this.pVel[i * 3 + 2] *= drag;
      this.pVel[i * 3 + 1] = this.pVel[i * 3 + 1] * drag - this.pGrav[i] * dt;
      this.pPos[i * 3] += this.pVel[i * 3] * dt;
      this.pPos[i * 3 + 1] += this.pVel[i * 3 + 1] * dt;
      this.pPos[i * 3 + 2] += this.pVel[i * 3 + 2] * dt;
      if (this.pPos[i * 3 + 1] < 0.02) {
        this.pPos[i * 3 + 1] = 0.02;
        this.pVel[i * 3 + 1] *= -0.24;
        this.pVel[i * 3] *= 0.5;
        this.pVel[i * 3 + 2] *= 0.5;
      }
      const t = this.pLife[i] / this.pMax[i];
      const flicker = 0.55 + 0.45 * Math.sin(this.time * 44 + i * 4.1);
      this.pCol[i * 3] = this.pBase[i * 3] * t * flicker;
      this.pCol[i * 3 + 1] = this.pBase[i * 3 + 1] * t * flicker;
      this.pCol[i * 3 + 2] = this.pBase[i * 3 + 2] * t * flicker;
    }
    this.points.geometry.attributes.position.needsUpdate = true;
    this.points.geometry.attributes.color.needsUpdate = true;

    for (const slot of this.casings) {
      if (!slot.mesh.visible) continue;
      slot.life -= dt;
      if (slot.life <= 0 || slot.mesh.position.y < -1) { slot.mesh.visible = false; continue; }
      slot.vy -= 15 * dt;
      slot.mesh.position.x += slot.vx * dt;
      slot.mesh.position.y += slot.vy * dt;
      slot.mesh.position.z += slot.vz * dt;
      if (slot.mesh.position.y < 0.025) {
        slot.mesh.position.y = 0.025;
        slot.vy *= -0.33;
        slot.vx *= 0.45;
        slot.vz *= 0.45;
        slot.spin *= 0.5;
      }
      slot.mesh.rotation.x += slot.spin * dt;
      slot.mesh.rotation.z += slot.spin * 0.7 * dt;
    }

    for (const slot of this.rings) {
      if (!slot.mesh.visible) continue;
      slot.life -= dt;
      if (slot.life <= 0) { slot.mesh.visible = false; continue; }
      const t = 1 - slot.life / slot.max;
      slot.mesh.scale.setScalar(0.35 + t * slot.grow);
      slot.mesh.material.opacity = (1 - t) * 0.8;
    }

    if (this.flash.intensity > 0) {
      this.flash.intensity = Math.max(0, this.flash.intensity - dt * 520);
    }
  }
}

import * as THREE from 'three';
import {
  asphaltTexture, concreteTexture, metalTexture, containerTexture, hazardTexture,
  signTexture, groundNumberTexture, puddleTexture, skyTexture, smokeTexture
} from './textures.js';

const PI = Math.PI;

export function buildWorld(scene, renderer) {
  const colliders = [];
  const occluders = [];
  const animated = [];
  const steam = [];
  const rand = seeded(9182);
  const root = new THREE.Group();
  scene.add(root);

  scene.fog = new THREE.FogExp2(0x071018, 0.019);
  scene.background = new THREE.Color(0x03060a);

  const asphalt = asphaltTexture();
  const concrete = concreteTexture();
  const metal = metalTexture('#252b2f', 12);
  const metalLight = metalTexture('#3b4448', 7);

  const mat = {
    floor: new THREE.MeshPhysicalMaterial({ map: asphalt, color: 0x9aa3a6, roughness: 0.55, metalness: 0.35, clearcoat: 0.65, clearcoatRoughness: 0.2, envMapIntensity: 0.9 }),
    concrete: new THREE.MeshStandardMaterial({ map: concrete, color: 0xaeb4b4, roughness: 0.9, metalness: 0.05, envMapIntensity: 0.4 }),
    concreteDark: new THREE.MeshStandardMaterial({ map: concrete, color: 0x575e60, roughness: 0.95, metalness: 0.04, envMapIntensity: 0.25 }),
    metal: new THREE.MeshStandardMaterial({ map: metal, color: 0x8f9da2, roughness: 0.45, metalness: 0.88, envMapIntensity: 0.9 }),
    metalDark: new THREE.MeshStandardMaterial({ map: metal, color: 0x4c585d, roughness: 0.55, metalness: 0.82, envMapIntensity: 0.7 }),
    metalLight: new THREE.MeshStandardMaterial({ map: metalLight, color: 0x9da7a9, roughness: 0.42, metalness: 0.8, envMapIntensity: 0.75 }),
    rubber: new THREE.MeshStandardMaterial({ color: 0x101316, roughness: 0.92, metalness: 0.05 }),
    wood: new THREE.MeshStandardMaterial({ color: 0x64513a, roughness: 0.85, metalness: 0.08 }),
    hazard: new THREE.MeshStandardMaterial({ map: hazardTexture(), color: 0xc7a466, roughness: 0.68, metalness: 0.45 }),
    amber: new THREE.MeshBasicMaterial({ color: 0xff8a2a, toneMapped: false }),
    cyan: new THREE.MeshBasicMaterial({ color: 0x5fe9ff, toneMapped: false }),
    red: new THREE.MeshBasicMaterial({ color: 0xff2f2f, toneMapped: false }),
    bulb: new THREE.MeshBasicMaterial({ color: 0xffd7a1, toneMapped: false }),
    glass: new THREE.MeshStandardMaterial({ color: 0x19313c, roughness: 0.12, metalness: 0.9, envMapIntensity: 1.2 }),
    black: new THREE.MeshStandardMaterial({ color: 0x07090a, roughness: 0.8, metalness: 0.2 })
  };

  function addBox(w, h, d, material, x, y, z, ry = 0, solid = true, cast = true) {
    const mesh = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), material);
    mesh.position.set(x, y, z);
    mesh.rotation.y = ry;
    mesh.castShadow = cast;
    mesh.receiveShadow = true;
    root.add(mesh);
    if (solid) {
      registerCollider(mesh, w, d, ry);
      occluders.push(mesh);
    }
    return mesh;
  }

  function registerCollider(mesh, w, d, ry) {
    const c = Math.abs(Math.cos(ry));
    const s = Math.abs(Math.sin(ry));
    const ex = (w * c + d * s) / 2;
    const ez = (w * s + d * c) / 2;
    colliders.push({ minX: mesh.position.x - ex, maxX: mesh.position.x + ex, minZ: mesh.position.z - ez, maxZ: mesh.position.z + ez, mesh });
  }

  function addPlane(w, h, material, x, y, z, rx = -PI / 2, ry = 0, rz = 0) {
    const mesh = new THREE.Mesh(new THREE.PlaneGeometry(w, h), material);
    mesh.position.set(x, y, z);
    mesh.rotation.set(rx, ry, rz);
    mesh.receiveShadow = true;
    root.add(mesh);
    return mesh;
  }

  // ---------------- ground ----------------
  const floor = addPlane(82, 82, mat.floor, 0, 0, -2);
  floor.receiveShadow = true;
  occluders.push(floor);

  const puddleTex = puddleTexture();
  for (let i = 0; i < 12; i++) {
    const p = new THREE.Mesh(new THREE.PlaneGeometry(4 + rand() * 7, 2.4 + rand() * 4.5), new THREE.MeshBasicMaterial({ map: puddleTex, transparent: true, opacity: 0.13 + rand() * 0.08, color: 0x72cfe2, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false }));
    p.rotation.set(-PI / 2, 0, rand() * PI);
    p.position.set((rand() - 0.5) * 54, 0.012 + rand() * 0.003, -6 + (rand() - 0.5) * 50);
    root.add(p);
  }

  const number = new THREE.Mesh(new THREE.PlaneGeometry(8.5, 8.5), new THREE.MeshBasicMaterial({ map: groundNumberTexture('07'), transparent: true, opacity: 0.5, depthWrite: false, toneMapped: false }));
  number.rotation.x = -PI / 2;
  number.position.set(0, 0.015, 8);
  root.add(number);

  for (let i = 0; i < 8; i++) {
    const line = new THREE.Mesh(new THREE.PlaneGeometry(0.1, 7.5), new THREE.MeshBasicMaterial({ color: 0xb58c33, transparent: true, opacity: 0.28 }));
    line.rotation.x = -PI / 2;
    line.position.set(-17.5 + i * 5, 0.013, 19.5);
    root.add(line);
  }

  // ---------------- perimeter ----------------
  addBox(62, 6.8, 1.2, mat.concrete, 0, 3.4, -31, 0);
  addBox(1.2, 6.8, 64, mat.concrete, -30.5, 3.4, -2, 0);
  addBox(1.2, 6.8, 64, mat.concrete, 30.5, 3.4, -2, 0);
  addBox(62, 6.8, 1.2, mat.concrete, 0, 3.4, 27, 0, true, false);

  // wall ribs and trim
  for (let x = -28; x <= 28; x += 7) {
    addBox(0.34, 6.6, 1.4, mat.concreteDark, x, 3.3, -30.35, 0, false, false);
  }
  for (let z = -28; z <= 24; z += 8) {
    addBox(1.4, 6.6, 0.34, mat.concreteDark, -29.85, 3.3, z, 0, false, false);
    addBox(1.4, 6.6, 0.34, mat.concreteDark, 29.85, 3.3, z, 0, false, false);
  }
  addBox(60, 0.12, 0.16, mat.cyan, 0, 6.15, -30.4, 0, false, false);
  addBox(0.16, 0.12, 61, mat.cyan, -29.9, 6.15, -2, 0, false, false);
  addBox(0.16, 0.12, 61, mat.cyan, 29.9, 6.15, -2, 0, false, false);

  // ---------------- facility / back building ----------------
  addBox(34, 7.2, 6, mat.concreteDark, 0, 3.6, -27.4, 0);
  addBox(35, 0.5, 6.8, mat.metal, 0, 7.35, -27.4, 0, false, false);
  addBox(30, 2.2, 0.35, mat.metalDark, 0, 5.9, -24.25, 0, false, false);
  for (let x = -14; x <= 14; x += 4) {
    addBox(0.45, 5.6, 0.4, mat.metal, x, 2.9, -24.15, 0, false, false);
  }
  // roll-up door
  addBox(8.4, 4.5, 0.26, mat.metal, 0, 2.25, -24.1, 0, false, false);
  for (let y = 0.35; y < 4.4; y += 0.34) addBox(8.1, 0.07, 0.3, mat.metalDark, 0, y, -23.95, 0, false, false);
  addBox(9.2, 0.5, 0.45, mat.hazard, 0, 4.65, -24.0, 0, false, false);
  addBox(0.42, 4.5, 0.4, mat.hazard, -4.3, 2.25, -23.9, 0, false, false);
  addBox(0.42, 4.5, 0.4, mat.hazard, 4.3, 2.25, -23.9, 0, false, false);

  // windows
  for (let i = 0; i < 6; i++) {
    const win = addBox(2.4, 0.9, 0.1, mat.glass, -12.5 + i * 5, 6.2, -24.06, 0, false, false);
    const glow = new THREE.Mesh(new THREE.PlaneGeometry(2.25, 0.72), new THREE.MeshBasicMaterial({ color: i % 2 ? 0x4a7b83 : 0x8c7444, transparent: true, opacity: 0.18, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false }));
    glow.position.set(win.position.x, 6.2, -24.0);
    root.add(glow);
  }

  const sign = new THREE.Mesh(new THREE.PlaneGeometry(10, 3.3), new THREE.MeshBasicMaterial({ map: signTexture('SECTOR 07', 'AUTHORIZED PERSONNEL ONLY', '#ff9a38'), transparent: true, toneMapped: false }));
  sign.position.set(0, 5.55, -24.05);
  root.add(sign);

  const sideSign = new THREE.Mesh(new THREE.PlaneGeometry(7.4, 2.4), new THREE.MeshBasicMaterial({ map: signTexture('RESTRICTED', 'USE OF FORCE AUTHORIZED', '#ff4c38', 8), transparent: true, toneMapped: false }));
  sideSign.position.set(-28.8, 4.3, -16);
  sideSign.rotation.y = PI / 2;
  root.add(sideSign);

  // loading dock
  addBox(15, 1.1, 4.2, mat.concreteDark, 0, 0.55, -21.1, 0);
  addBox(15.2, 0.22, 0.24, mat.hazard, 0, 1.08, -19.03, 0, false, false);
  for (let i = 0; i < 5; i++) {
    addBox(0.24, 0.75, 0.5, mat.metalDark, -6 + i * 3, 0.32, -18.85, 0, false, false);
  }

  // ---------------- catwalk above ----------------
  addBox(25, 0.24, 2.0, mat.metal, 0, 5.35, -22.8, 0, false, false);
  for (let x = -12; x <= 12; x += 2) {
    addBox(0.08, 1.1, 0.08, mat.metal, x, 6.0, -21.85, 0, false, false);
    addBox(0.08, 1.1, 0.08, mat.metal, x, 6.0, -23.75, 0, false, false);
  }
  addBox(24, 0.08, 0.08, mat.metalLight, 0, 6.52, -21.85, 0, false, false);
  addBox(24, 0.08, 0.08, mat.metalLight, 0, 6.52, -23.75, 0, false, false);
  for (let x = -12; x <= 12; x += 4) addBox(0.1, 1.18, 0.1, mat.metal, x, 6.0, -22.8, 0, false, false);
  for (let i = 0; i < 4; i++) {
    const bulb = addBox(0.55, 0.09, 0.16, mat.bulb, -9 + i * 6, 5.2, -22.8, 0, false, false);
    bulb.castShadow = false;
  }

  // ---------------- containers ----------------
  const containerDefs = [
    [-12, -5, 0, '#384b4b', '#9a4c24', 11],
    [12.6, -8, 0, '#4b3f39', '#a2552b', 13],
    [-15, -15.5, PI / 2, '#3b414a', '#8d4524', 15],
    [16.5, 3.5, PI / 2, '#3e4940', '#9b5c28', 17],
    [8.5, -17, 0, '#4a3c3b', '#a04c26', 19],
    [-6.5, 9.5, PI / 2, '#344044', '#9c552c', 21]
  ];
  function container(x, z, ry, color, accent, seed, stackY = 0) {
    const tex = containerTexture(color, accent, seed);
    const material = new THREE.MeshStandardMaterial({ map: tex, color: 0xaab0ad, roughness: 0.62, metalness: 0.55, envMapIntensity: 0.6 });
    addBox(2.55, 2.7, 6.15, material, x, 1.35 + stackY, z, ry);
    const along = ry === 0 ? [0, 0, 6.3] : [6.3, 0, 0];
    const across = ry === 0 ? [2.7, 0, 0] : [0, 0, 2.7];
    for (const sx of [-1, 1]) {
      for (const sz of [-1, 1]) {
        addBox(0.15, 2.8, 0.15, mat.metalDark, x + (ry === 0 ? sx * 1.28 : sz * 3.08), 1.35 + stackY, z + (ry === 0 ? sz * 3.08 : sx * 1.28), 0, false, false);
      }
    }
    addBox(ry === 0 ? 2.7 : 6.2, 0.13, ry === 0 ? 6.2 : 2.7, mat.metalDark, x, 0.12 + stackY, z, 0, false, false);
    addBox(ry === 0 ? 2.7 : 6.2, 0.13, ry === 0 ? 6.2 : 2.7, mat.metalDark, x, 2.76 + stackY, z, 0, false, false);
    if (stackY === 0) {
      const labelTex = signTexture(`MSKU ${seed}407`, 'MERIDIAN PORT AUTHORITY', '#b8a070', seed);
      const label = new THREE.Mesh(new THREE.PlaneGeometry(1.65, 0.55), new THREE.MeshBasicMaterial({ map: labelTex, transparent: true, opacity: 0.5, toneMapped: false }));
      label.position.set(x + (ry === 0 ? 0 : (across[0] > 0 ? 1.29 : 1.29)), 1.75, z + (ry === 0 ? 3.09 : 0));
      label.rotation.y = ry === 0 ? 0 : PI / 2;
      root.add(label);
    }
    return { x, z, ry };
  }
  for (const d of containerDefs) container(...d);
  // stacked second container
  container(-12, -5, 0, '#2d3d42', '#a55028', 23, 2.8);

  // ---------------- cover / props ----------------
  function barrier(x, z, ry = 0) {
    const b = addBox(3.2, 0.95, 0.65, mat.concrete, x, 0.475, z, ry);
    addBox(3.2, 0.12, 0.68, mat.hazard, x, 0.94, z, ry, false, false);
    addBox(3.0, 0.15, 0.7, mat.concreteDark, x, 0.12, z, ry, false, false);
    return b;
  }
  barrier(-2, 1.5, 0.18);
  barrier(5.6, 11, -0.5);
  barrier(-9, 14, 0.2);
  barrier(18, 12, PI / 2 - 0.1);
  barrier(-20, 2, PI / 2);
  barrier(3, -11.5, -0.1);

  function crate(x, z, y = 0.55, s = 1.1, ry = 0) {
    const m = addBox(s, s, s, mat.metalDark, x, y, z, ry);
    addBox(s * 1.02, 0.08, s * 1.02, mat.hazard, x, y + s * 0.33, z, ry, false, false);
    for (const ax of [-1, 1]) for (const az of [-1, 1]) {
      addBox(0.06, s * 1.01, 0.06, mat.metal, x + ax * s * 0.47, y, z + az * s * 0.47, ry, false, false);
    }
    return m;
  }
  crate(-9.7, -2.1, 0.55, 1.15, 0.12);
  crate(-8.7, -2.7, 0.55, 0.95, -0.2);
  crate(-9.4, -2.3, 1.7, 1.0, 0.1);
  crate(10.2, -4.6, 0.55, 1.2, 0.16);
  crate(11.2, -5.1, 0.55, 0.9, 0.4);
  crate(11.1, -4.8, 1.65, 1.0, 0.2);
  crate(-19.5, -10.2, 0.55, 1.15, 0.2);
  crate(21.5, -14.5, 0.55, 1.25, 0.1);
  crate(21.8, -14.2, 1.75, 1.0, 0.25);

  function barrel(x, z, color = 0xb65e22) {
    const cylinderMat = new THREE.MeshStandardMaterial({ color, roughness: 0.5, metalness: 0.7, envMapIntensity: 0.8 });
    const b = new THREE.Mesh(new THREE.CylinderGeometry(0.36, 0.38, 1.0, 14), cylinderMat);
    b.position.set(x, 0.5, z);
    b.castShadow = true; b.receiveShadow = true;
    root.add(b);
    const ring = new THREE.Mesh(new THREE.TorusGeometry(0.37, 0.035, 5, 16), mat.metal);
    ring.position.set(x, 0.78, z); ring.rotation.x = PI / 2; root.add(ring);
    const ring2 = ring.clone(); ring2.position.y = 0.25; root.add(ring2);
    const strip = new THREE.Mesh(new THREE.CylinderGeometry(0.373, 0.383, 0.18, 14, 1, true), new THREE.MeshBasicMaterial({ color: 0xd7a545, toneMapped: false }));
    strip.position.set(x, 0.55, z); root.add(strip);
    colliders.push({ minX: x - 0.38, maxX: x + 0.38, minZ: z - 0.38, maxZ: z + 0.38, mesh: b });
    occluders.push(b);
  }
  barrel(-16.7, 5.4); barrel(-17.5, 5.7, 0x3f5960); barrel(-16.9, 6.5);
  barrel(6.8, -14.6, 0x3f5960); barrel(7.5, -14.3); barrel(19.3, 6.9);
  barrel(-23.8, -4.3); barrel(-24.4, -3.5, 0x3f5960);

  // jersey blocks near spawn approach
  addBox(2.4, 0.8, 1.2, mat.concreteDark, -4.5, 0.4, 17.5, 0.25);
  addBox(2.4, 0.8, 1.2, mat.concreteDark, 11.5, 0.4, 17, -0.2);

  // ---------------- pipes and industrial dressing ----------------
  const pipeMat = new THREE.MeshStandardMaterial({ color: 0x536166, roughness: 0.4, metalness: 0.9, envMapIntensity: 0.7 });
  for (const [y, r] of [[5.1, 0.28], [4.5, 0.19], [6.05, 0.16]]) {
    const pipe = new THREE.Mesh(new THREE.CylinderGeometry(r, r, 58, 12), pipeMat);
    pipe.rotation.z = PI / 2;
    pipe.position.set(0, y, -29.1);
    pipe.castShadow = true;
    root.add(pipe);
  }
  for (let x = -25; x <= 25; x += 6.2) {
    const clamp = new THREE.Mesh(new THREE.TorusGeometry(0.32, 0.06, 5, 12), mat.metalDark);
    clamp.rotation.y = PI / 2;
    clamp.position.set(x, 5.1, -29.1);
    root.add(clamp);
  }
  for (const x of [-22, -8, 7, 20]) {
    addBox(0.2, 5.8, 0.2, mat.metalDark, x, 2.9, -29.1, 0, false, false);
    steam.push(new THREE.Vector3(x, 5.6, -28.7));
  }

  // vertical pipes at side wall
  for (let i = 0; i < 4; i++) {
    const pipe = new THREE.Mesh(new THREE.CylinderGeometry(0.12, 0.12, 6.2, 8), pipeMat);
    pipe.position.set(-29.7, 3.1, 16 - i * 2.1);
    root.add(pipe);
  }

  // ---------------- lamps / lights ----------------
  const lampGroup = new THREE.Group();
  root.add(lampGroup);
  const lampDefs = [
    [-18.5, 8.5, 0x9fe4ff],
    [18.5, 5.5, 0xffb667],
    [0, -16.2, 0xffb060],
    [-23, -18, 0x9fe4ff],
    [22, 17, 0xffa04d]
  ];
  const lampLights = [];
  function lamp(x, z, color) {
    const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.11, 0.15, 6.4, 8), mat.metalDark);
    pole.position.set(x, 3.2, z);
    pole.castShadow = true;
    root.add(pole);
    const arm = new THREE.Mesh(new THREE.BoxGeometry(0.09, 0.09, 1.6), mat.metalDark);
    arm.position.set(x, 6.3, z - 0.7);
    root.add(arm);
    const housing = new THREE.Mesh(new THREE.BoxGeometry(0.62, 0.22, 0.85), mat.metal);
    housing.position.set(x, 6.22, z - 1.4);
    housing.castShadow = true;
    root.add(housing);
    const bulb = new THREE.Mesh(new THREE.BoxGeometry(0.46, 0.06, 0.55), new THREE.MeshBasicMaterial({ color, toneMapped: false }));
    bulb.position.set(x, 6.1, z - 1.4);
    root.add(bulb);
    const light = new THREE.PointLight(color, 26, 23, 2);
    light.position.set(x, 5.95, z - 1.4);
    lampGroup.add(light);
    lampLights.push(light);
    const cone = new THREE.Mesh(
      new THREE.ConeGeometry(2.9, 6.0, 24, 1, true),
      new THREE.MeshBasicMaterial({ color, transparent: true, opacity: 0.026, side: THREE.DoubleSide, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false })
    );
    cone.position.set(x, 3.0, z - 1.4);
    root.add(cone);
    animated.push({ obj: cone, type: 'beam' });
    return light;
  }
  for (const [x, z, c] of lampDefs) lamp(x, z, c);

  // corner watch lights
  const spot = new THREE.SpotLight(0xbedcff, 90, 60, 0.22, 0.55, 1.4);
  spot.position.set(24, 9, 19);
  spot.target.position.set(0, 0, -7);
  scene.add(spot.target);
  scene.add(spot);
  const spotHousing = new THREE.Mesh(new THREE.CylinderGeometry(0.5, 0.34, 0.65, 12), mat.metalDark);
  spotHousing.position.set(24, 9, 19);
  spotHousing.rotation.x = 0.45;
  root.add(spotHousing);
  const spotLens = new THREE.Mesh(new THREE.CircleGeometry(0.41, 16), new THREE.MeshBasicMaterial({ color: 0xcfe9ff, toneMapped: false }));
  spotLens.position.set(24, 8.82, 19.34);
  spotLens.rotation.x = -0.9;
  root.add(spotLens);

  // red hazard lights
  const redLights = [];
  for (const [x, y, z] of [[-15, 6.8, -24.1], [15, 6.8, -24.1], [0, 0.55, 9.6]]) {
    const m = new THREE.Mesh(new THREE.SphereGeometry(0.075, 8, 6), mat.red);
    m.position.set(x, y, z);
    root.add(m);
    const l = new THREE.PointLight(0xff2f24, 3, 4.5, 2);
    l.position.copy(m.position);
    scene.add(l);
    redLights.push({ mesh: m, light: l, phase: rand() * PI * 2 });
  }

  // ---------------- sky / moon ----------------
  const sky = new THREE.Mesh(new THREE.SphereGeometry(240, 32, 16), new THREE.MeshBasicMaterial({ map: skyTexture(), side: THREE.BackSide, fog: false, toneMapped: false }));
  sky.rotation.y = 0.7;
  scene.add(sky);

  const moon = new THREE.Mesh(new THREE.CircleGeometry(6, 32), new THREE.MeshBasicMaterial({ color: 0xcfdfec, transparent: true, opacity: 0.44, toneMapped: false, fog: false }));
  moon.position.set(-58, 72, -140);
  moon.lookAt(0, 2, 0);
  scene.add(moon);
  const moonGlow = new THREE.Sprite(new THREE.SpriteMaterial({ map: new THREE.CanvasTexture(moonCanvas()), color: 0x86b6d6, transparent: true, opacity: 0.34, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false, fog: false }));
  moonGlow.position.copy(moon.position);
  moonGlow.scale.setScalar(54);
  scene.add(moonGlow);

  // distant skyline silhouettes
  for (let i = 0; i < 26; i++) {
    const w = 2 + rand() * 7;
    const h = 3 + rand() * 16;
    const b = new THREE.Mesh(new THREE.BoxGeometry(w, h, 2.5), new THREE.MeshBasicMaterial({ color: 0x071018, fog: false }));
    const a = -0.9 + rand() * 1.8;
    b.position.set(Math.sin(a) * 115, h / 2 - 1, -Math.cos(a) * 115 - 18);
    scene.add(b);
    if (rand() > 0.45) {
      const lit = new THREE.Mesh(new THREE.PlaneGeometry(0.14, 0.14), new THREE.MeshBasicMaterial({ color: rand() > 0.2 ? 0xff9f4a : 0x7be6ff, toneMapped: false, fog: false }));
      lit.position.set(b.position.x + (rand() - 0.5) * w * 0.7, 1 + rand() * h, b.position.z + 1.3);
      scene.add(lit);
    }
  }

  // ---------------- lights ----------------
  const hemi = new THREE.HemisphereLight(0x51708f, 0x06090b, 0.9);
  scene.add(hemi);
  const moonLight = new THREE.DirectionalLight(0x9cbfe6, 1.35);
  moonLight.position.set(-28, 38, 18);
  moonLight.target.position.set(0, 0, -4);
  scene.add(moonLight.target);
  moonLight.castShadow = true;
  moonLight.shadow.mapSize.set(1024, 1024);
  moonLight.shadow.camera.left = -40;
  moonLight.shadow.camera.right = 40;
  moonLight.shadow.camera.top = 40;
  moonLight.shadow.camera.bottom = -40;
  moonLight.shadow.camera.near = 1;
  moonLight.shadow.camera.far = 90;
  moonLight.shadow.bias = -0.0004;
  moonLight.shadow.normalBias = 0.025;
  scene.add(moonLight);
  const fill = new THREE.DirectionalLight(0x17415c, 0.6);
  fill.position.set(20, 12, -20);
  scene.add(fill);

  // ---------------- rain ----------------
  const dropCount = 1900;
  const rainPos = new Float32Array(dropCount * 6);
  const drops = [];
  for (let i = 0; i < dropCount; i++) {
    drops.push({
      x: (rand() - 0.5) * 58,
      y: rand() * 24,
      z: (rand() - 0.5) * 58,
      v: 15 + rand() * 11,
      len: 0.5 + rand() * 0.9
    });
  }
  const rainGeo = new THREE.BufferGeometry();
  rainGeo.setAttribute('position', new THREE.BufferAttribute(rainPos, 3));
  const rainMat = new THREE.LineBasicMaterial({ color: 0xa8d3e2, transparent: true, opacity: 0.25, blending: THREE.AdditiveBlending, depthWrite: false, toneMapped: false });
  const rain = new THREE.LineSegments(rainGeo, rainMat);
  rain.frustumCulled = false;
  scene.add(rain);

  // ---------------- mist ----------------
  const mistTex = smokeTexture();
  const mists = [];
  for (let i = 0; i < 9; i++) {
    const m = new THREE.Sprite(new THREE.SpriteMaterial({ map: mistTex, color: 0x71909a, transparent: true, opacity: 0.036, depthWrite: false }));
    m.position.set((rand() - 0.5) * 46, 0.8 + rand() * 1.4, -8 + (rand() - 0.5) * 45);
    m.scale.set(11 + rand() * 10, 4 + rand() * 3, 1);
    scene.add(m);
    mists.push({ sprite: m, speed: 0.07 + rand() * 0.1, phase: rand() * 10 });
  }

  // lightning
  const lightningLight = new THREE.DirectionalLight(0xb8d4ff, 0);
  lightningLight.position.set(10, 40, -30);
  scene.add(lightningLight);
  let lightningTimer = 10 + rand() * 8;
  let lightningPulse = 0;

  const spawnPoints = [
    { x: -23, z: -20 }, { x: 23, z: -19 }, { x: -24, z: 8 },
    { x: 24, z: 10 }, { x: -18, z: -24 }, { x: 18, z: -24 }
  ];

  const steamTimers = steam.map(() => rand() * 2);

  function update(dt, time, playerPos, effects) {
    // rain
    const arr = rainGeo.attributes.position.array;
    for (let i = 0; i < drops.length; i++) {
      const d = drops[i];
      d.y -= d.v * dt;
      d.x += 1.3 * dt;
      if (d.y < 0) {
        d.y = 18 + Math.random() * 8;
        d.x = playerPos.x + (Math.random() - 0.5) * 48;
        d.z = playerPos.z + (Math.random() - 0.5) * 48;
      }
      if (Math.abs(d.x - playerPos.x) > 27) d.x = playerPos.x + (Math.random() - 0.5) * 48;
      if (Math.abs(d.z - playerPos.z) > 27) d.z = playerPos.z + (Math.random() - 0.5) * 48;
      const j = i * 6;
      arr[j] = d.x;
      arr[j + 1] = d.y;
      arr[j + 2] = d.z;
      arr[j + 3] = d.x - 0.045;
      arr[j + 4] = d.y + d.len;
      arr[j + 5] = d.z + 0.02;
    }
    rainGeo.attributes.position.needsUpdate = true;

    // mist drift
    for (const m of mists) {
      m.sprite.position.x += m.speed * dt;
      m.sprite.position.y += Math.sin(time * 0.3 + m.phase) * 0.006;
      if (m.sprite.position.x > 28) m.sprite.position.x = -28;
    }

    // lamp flicker
    for (let i = 0; i < lampLights.length; i++) {
      const l = lampLights[i];
      const base = 26;
      l.intensity = base + Math.sin(time * 14 + i * 3.4) * 0.7 + (Math.random() - 0.5) * 0.5;
    }
    for (const r of redLights) {
      const pulse = (Math.sin(time * 3.4 + r.phase) + 1) * 0.5;
      r.light.intensity = 1 + pulse * 4.5;
      r.mesh.scale.setScalar(0.85 + pulse * 0.3);
    }

    // steam vents
    if (effects) {
      for (let i = 0; i < steam.length; i++) {
        steamTimers[i] -= dt;
        if (steamTimers[i] <= 0) {
          steamTimers[i] = 1.6 + Math.random() * 2.2;
          effects.smokeAt(steam[i].clone().add(new THREE.Vector3((Math.random() - 0.5) * 0.3, 0, (Math.random() - 0.5) * 0.3)), 0.5, 2.2, 0x91a5aa, 0.35);
        }
      }
    }

    // lightning
    lightningTimer -= dt;
    if (lightningTimer <= 0) {
      lightningTimer = 12 + Math.random() * 16;
      lightningPulse = 0.24;
      document.getElementById('lightning-flash')?.classList.remove('flash');
      void document.getElementById('lightning-flash')?.offsetWidth;
      document.getElementById('lightning-flash')?.classList.add('flash');
    }
    if (lightningPulse > 0) {
      lightningPulse -= dt;
      lightningLight.intensity = Math.max(0, lightningPulse * 35 * (0.6 + Math.random() * 0.5));
    } else lightningLight.intensity = 0;
  }

  return { root, colliders, occluders, spawnPoints, update, lampLights, moonLight, hemi, floor };
}

function seeded(seed) {
  let t = seed >>> 0;
  return () => {
    t += 0x6d2b79f5;
    let r = Math.imul(t ^ (t >>> 15), 1 | t);
    r ^= r + Math.imul(r ^ (r >>> 7), 61 | r);
    return ((r ^ (r >>> 14)) >>> 0) / 4294967296;
  };
}

function moonCanvas() {
  const c = document.createElement('canvas');
  c.width = c.height = 256;
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(128, 128, 8, 128, 128, 128);
  g.addColorStop(0, 'rgba(226,242,255,0.9)');
  g.addColorStop(0.14, 'rgba(186,218,244,0.62)');
  g.addColorStop(0.4, 'rgba(100,150,190,0.16)');
  g.addColorStop(1, 'rgba(40,80,120,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, 256, 256);
  return c;
}

import * as THREE from 'three';
import { audio } from './audio.js';

const _muzzle = new THREE.Vector3();
const _dir = new THREE.Vector3();

function damp(current, target, lambda, dt) {
  return THREE.MathUtils.lerp(current, target, 1 - Math.exp(-lambda * dt));
}

export class Weapon {
  constructor(camera, effects) {
    this.camera = camera;
    this.effects = effects;
    this.group = new THREE.Group();
    this.group.scale.setScalar(1);
    camera.add(this.group);

    this.magSize = 30;
    this.ammo = 30;
    this.reserve = 210;
    this.reloading = false;
    this.reloadTime = 0;
    this.reloadDuration = 1.75;
    this.cooldown = 0;
    this.fireRate = 0.092;
    this.ads = false;
    this.adsAmount = 0;
    this.recoil = 0;
    this.recoilKick = 0;
    this.recoilYaw = 0;
    this.bobTime = 0;
    this.swayX = 0;
    this.swayY = 0;
    this.shotsFired = 0;
    this.hits = 0;
    this.triggerHeld = false;
    this.heat = 0;

    this.hipPos = new THREE.Vector3(0.302, -0.255, -0.56);
    this.adsPos = new THREE.Vector3(0, -0.153, -0.40);
    this.basePos = this.hipPos.clone();

    this.build();

    this.muzzleAnchor = new THREE.Object3D();
    this.muzzleAnchor.position.set(0, 0.018, -0.955);
