    this.casingAnchor = new THREE.Object3D();
    this.casingAnchor.position.set(0.11, 0.03, -0.07);
    this.group.add(this.casingAnchor);

    this.group.traverse(o => {
      if (o.isMesh) { o.castShadow = false; o.receiveShadow = false; o.frustumCulled = false; }
    });
  }

  build() {
    const gunmetal = new THREE.MeshStandardMaterial({ color: 0x242a2e, roughness: 0.34, metalness: 0.95, envMapIntensity: 1.1 });
    const gunmetalDark = new THREE.MeshStandardMaterial({ color: 0x111518, roughness: 0.44, metalness: 0.88, envMapIntensity: 0.8 });
    const polymer = new THREE.MeshStandardMaterial({ color: 0x15191b, roughness: 0.76, metalness: 0.18 });
    const polymer2 = new THREE.MeshStandardMaterial({ color: 0x232a2c, roughness: 0.7, metalness: 0.22 });
    const accent = new THREE.MeshStandardMaterial({ color: 0xff7a1a, emissive: 0xff5a00, emissiveIntensity: 1.6, roughness: 0.5, metalness: 0.4 });
    const glow = new THREE.MeshBasicMaterial({ color: 0x8df6ff, toneMapped: false });
    const glass = new THREE.MeshStandardMaterial({ color: 0x16303a, roughness: 0.08, metalness: 0.8, transparent: true, opacity: 0.55, envMapIntensity: 1.8 });
    const glove = new THREE.MeshStandardMaterial({ color: 0x1b2022, roughness: 0.9, metalness: 0.02 });
    const glovePlate = new THREE.MeshStandardMaterial({ color: 0x2e373a, roughness: 0.65, metalness: 0.25 });

    const add = (geo, material, x, y, z, rx = 0, ry = 0, rz = 0) => {
      const mesh = new THREE.Mesh(geo, material);
      mesh.position.set(x, y, z);
      mesh.rotation.set(rx, ry, rz);
      this.group.add(mesh);
      return mesh;
    };
    const box = (w, h, d, m, x, y, z, rx = 0, ry = 0, rz = 0) => add(new THREE.BoxGeometry(w, h, d), m, x, y, z, rx, ry, rz);

    // receiver
    box(0.150, 0.165, 0.50, gunmetal, 0, 0, -0.015);
    box(0.135, 0.095, 0.34, gunmetalDark, 0, 0.055, -0.08);
    box(0.158, 0.045, 0.46, gunmetalDark, 0, 0.103, -0.04);
    // ejection port + bolt
    box(0.012, 0.065, 0.14, polymer, 0.077, 0.015, -0.04);
    box(0.006, 0.045, 0.045, gunmetalDark, 0.084, 0.035, 0.08);
    // charging handle
    box(0.03, 0.03, 0.16, gunmetalDark, 0.086, 0.052, 0.145);
    box(0.06, 0.025, 0.04, polymer2, 0.095, 0.052, 0.20);
    // top rail
    for (let i = 0; i < 13; i++) {
      box(0.085, 0.014, 0.026, gunmetalDark, 0, 0.137, -0.235 + i * 0.036);
    }
    // handguard
    box(0.135, 0.145, 0.46, polymer2, 0, -0.003, -0.46);
    for (let i = 0; i < 7; i++) {
      box(0.143, 0.02, 0.028, polymer, 0, 0.058, -0.63 + i * 0.06);
      box(0.143, 0.02, 0.028, polymer, 0, -0.064, -0.63 + i * 0.06);
    }
    box(0.152, 0.022, 0.40, gunmetalDark, 0, 0.078, -0.46);
    box(0.03, 0.022, 0.20, accent, 0.078, 0.005, -0.45);
    box(0.018, 0.018, 0.24, accent, -0.076, -0.035, -0.44);
    // barrel
    const barrel = add(new THREE.CylinderGeometry(0.027, 0.031, 0.46, 12), gunmetal, 0, 0.012, -0.78, Math.PI / 2, 0, 0);
    barrel.rotation.x = Math.PI / 2;
    const shroud = add(new THREE.CylinderGeometry(0.045, 0.043, 0.16, 12), gunmetalDark, 0, 0.012, -0.64, Math.PI / 2, 0, 0);
    shroud.rotation.x = Math.PI / 2;
    // muzzle brake
    const brake = add(new THREE.CylinderGeometry(0.043, 0.037, 0.12, 10), gunmetalDark, 0, 0.014, -0.965, Math.PI / 2, 0, 0);
    brake.rotation.x = Math.PI / 2;
    const brakeRing = add(new THREE.CylinderGeometry(0.048, 0.048, 0.025, 10), accent, 0, 0.014, -0.925, Math.PI / 2, 0, 0);
    brakeRing.rotation.x = Math.PI / 2;
    for (let i = 0; i < 3; i++) {
      box(0.095, 0.012, 0.022, gunmetal, 0, 0.058 + i * 0.001, -0.75 + i * 0.045);
    }
    // gas block
    box(0.075, 0.075, 0.08, gunmetalDark, 0, 0.03, -0.69);
    // magazine
    this.mag = box(0.095, 0.27, 0.155, polymer, 0, -0.19, 0.045, 0.22, 0, 0);
    box(0.076, 0.04, 0.12, gunmetalDark, 0, -0.315, 0.015, 0.22);
    box(0.01, 0.09, 0.02, accent, 0.049, -0.17, 0.035, 0.22);
    // grip
    box(0.082, 0.21, 0.11, polymer, 0, -0.19, 0.235, -0.28);
    box(0.09, 0.028, 0.12, polymer2, 0, -0.285, 0.27, -0.28);
    // trigger guard
    box(0.06, 0.016, 0.15, gunmetalDark, 0, -0.115, 0.12);
    box(0.014, 0.056, 0.02, gunmetalDark, 0, -0.095, 0.19, 0, 0, 0.1);
    // stock
    box(0.08, 0.11, 0.30, polymer, 0, 0.002, 0.39);
    box(0.11, 0.19, 0.07, polymer2, 0, -0.02, 0.545);
    box(0.10, 0.06, 0.26, gunmetalDark, 0, 0.068, 0.40);
    box(0.12, 0.035, 0.03, accent, 0, -0.085, 0.56);
    // optic
    box(0.085, 0.07, 0.16, gunmetalDark, 0, 0.178, -0.075);
    box(0.105, 0.028, 0.20, gunmetal, 0, 0.212, -0.075);
    const opticBody = add(new THREE.CylinderGeometry(0.058, 0.058, 0.16, 16), gunmetal, 0, 0.19, 0.008, Math.PI / 2, 0, 0);
    opticBody.rotation.x = Math.PI / 2;
    const lens = add(new THREE.CircleGeometry(0.048, 20), glass, 0, 0.19, -0.078);
    lens.rotation.y = Math.PI;
    const dot = add(new THREE.CircleGeometry(0.0065, 12), glow, 0, 0.19, -0.081);
    dot.rotation.y = Math.PI;
    box(0.05, 0.03, 0.05, gunmetal, 0.062, 0.195, -0.05);
    box(0.05, 0.03, 0.05, gunmetal, -0.062, 0.195, -0.05);
    // small front sight backup
    box(0.03, 0.07, 0.025, gunmetalDark, 0, 0.105, -0.64);
    // sling
    box(0.012, 0.18, 0.03, glove, 0.082, -0.07, 0.31, 0.2);
    // hands
    const right = add(new THREE.SphereGeometry(0.072, 12, 10), glove, 0.02, -0.22, 0.25);
    right.scale.set(0.9, 1.2, 0.9);
    box(0.085, 0.055, 0.105, glovePlate, 0.02, -0.185, 0.225);
    box(0.10, 0.10, 0.16, glove, 0.005, -0.31, 0.21);
    const left = add(new THREE.SphereGeometry(0.075, 12, 10), glove, -0.045, -0.16, -0.47);
    left.scale.set(0.85, 1.05, 1.25);
    box(0.09, 0.06, 0.12, glovePlate, -0.06, -0.115, -0.46);
    box(0.12, 0.10, 0.24, glove, -0.09, -0.225, -0.38, 0.35, 0, 0.1);
    // wrist details
    box(0.06, 0.06, 0.12, glovePlate, -0.05, -0.245, -0.30, 0.35);

    // tiny status screen
    box(0.034, 0.022, 0.004, glow, 0.048, 0.056, 0.128);
  }

  get muzzleWorld() {
    this.muzzleAnchor.getWorldPosition(_muzzle);
    return _muzzle;
  }

  getForward() {
    this.camera.getWorldDirection(_dir);
    return _dir;
  }

  setAds(on) {
    this.ads = on;
  }

  startReload() {
    if (this.reloading || this.ammo >= this.magSize || this.reserve <= 0) return false;
    this.reloading = true;
    this.reloadTime = 0;
    audio.reload(this.reloadDuration);
    return true;
  }

  finishReload() {
    const need = this.magSize - this.ammo;
    const take = Math.min(need, this.reserve);
    this.ammo += take;
    this.reserve -= take;
    this.reloading = false;
  }

  tryFire() {
    if (this.reloading) return false;
    if (this.cooldown > 0) return false;
    if (this.ammo <= 0) {
      audio.empty();
      this.cooldown = 0.28;
      this.startReload();
      return false;
    }
    this.ammo -= 1;
    this.shotsFired += 1;
    this.cooldown += this.fireRate;
    this.recoil = Math.min(2.1, this.recoil + 0.62 + Math.random() * 0.2);
    this.recoilKick += (this.ads ? 0.0105 : 0.018) + Math.random() * 0.004;
    this.recoilYaw += (Math.random() - 0.5) * (this.ads ? 0.004 : 0.009);
    this.heat = Math.min(1, this.heat + 0.16);
    audio.shot();
    const muzzle = this.muzzleWorld;
    const forward = this.getForward();
    this.effects.muzzleFlash(muzzle, forward, this.ads ? 0.85 : 1.12);
    this.effects.tracer(muzzle, muzzle.clone().addScaledVector(forward, 28), 0xffd9a0, 0.05);
    const casingPos = new THREE.Vector3();
    this.casingAnchor.getWorldPosition(casingPos);
    this.effects.casing(casingPos, new THREE.Vector3(1.8 + Math.random(), 1.6 + Math.random() * 1.2, 0.4 + Math.random()));
    return true;
  }

  update(dt, state) {
    this.cooldown = Math.max(0, this.cooldown - dt);
    this.heat = Math.max(0, this.heat - dt * 0.42);
    this.adsAmount = damp(this.adsAmount, this.ads ? 1 : 0, 14, dt);
    if (this.reloading) {
      this.reloadTime += dt;
      if (this.reloadTime >= this.reloadDuration) this.finishReload();
    }

    const moving = !state.grounded ? 0 : Math.min(1, state.speed / 6.2);
    const sprint = state.sprinting ? 1 : 0;
    this.bobTime += dt * (7.2 + moving * 3.2 + sprint * 2.5);
    const bobAmt = moving * (1 - this.adsAmount * 0.85) * (0.7 + sprint * 0.5);
    const bobX = Math.sin(this.bobTime) * 0.014 * bobAmt;
    const bobY = Math.abs(Math.cos(this.bobTime)) * 0.011 * bobAmt;
    const breathe = Math.sin(performance.now() * 0.0012) * 0.0025 * (1 - moving * 0.6);

    const targetSwayX = THREE.MathUtils.clamp(-state.lookX * 0.008, -0.045, 0.045);
    const targetSwayY = THREE.MathUtils.clamp(state.lookY * 0.006, -0.03, 0.03);
    this.swayX = damp(this.swayX, targetSwayX, 9, dt);
    this.swayY = damp(this.swayY, targetSwayY, 9, dt);

    this.recoil = damp(this.recoil, 0, 12, dt);
    const reloadProgress = this.reloading ? this.reloadTime / this.reloadDuration : 0;
    const reloadAnim = this.reloading ? Math.sin(Math.min(1, reloadProgress) * Math.PI) : 0;

    const hip = this.hipPos;
    const targetX = THREE.MathUtils.lerp(hip.x, this.adsPos.x, this.adsAmount) + bobX + this.swayX;
    const targetY = THREE.MathUtils.lerp(hip.y, this.adsPos.y, this.adsAmount) + bobY - breathe - reloadAnim * 0.16 + this.swayY;
    const targetZ = THREE.MathUtils.lerp(hip.z, this.adsPos.z, this.adsAmount) + this.recoil * 0.038;
    this.group.position.x = damp(this.group.position.x, targetX, 13, dt);
    this.group.position.y = damp(this.group.position.y, targetY, 13, dt);
    this.group.position.z = damp(this.group.position.z, targetZ, 14, dt);

    const sprintRot = sprint * (1 - this.adsAmount) * 0.22;
    const targetRotX = reloadAnim * 0.42 + this.recoil * 0.035 + sprintRot * 0.4;
    const targetRotY = -sprintRot * 0.7 + this.swayX * 0.8 + reloadAnim * 0.25;
    const targetRotZ = reloadAnim * 0.55 + this.recoil * 0.012 + sprintRot * 0.75;
    this.group.rotation.x = damp(this.group.rotation.x, targetRotX, 11, dt);
    this.group.rotation.y = damp(this.group.rotation.y, targetRotY, 11, dt);
    this.group.rotation.z = damp(this.group.rotation.z, targetRotZ, 11, dt);

    if (this.mag) {
      const drop = reloadProgress > 0.28 && reloadProgress < 0.66 ? Math.sin((reloadProgress - 0.28) / 0.38 * Math.PI) : 0;
      this.mag.position.y = -0.19 - drop * 0.34;
      this.mag.rotation.z = drop * 0.5;
    }
  }

  consumeRecoil() {
    const pitch = this.recoilKick;
    const yaw = this.recoilYaw;
    this.recoilKick = 0;
    this.recoilYaw = 0;
    return { pitch, yaw };
  }

  reset() {
    this.ammo = this.magSize;
    this.reserve = 210;
    this.reloading = false;
    this.reloadTime = 0;
    this.cooldown = 0;
    this.recoil = 0;
    this.shotsFired = 0;
    this.hits = 0;
    this.group.position.copy(this.hipPos);
    this.group.rotation.set(0, 0, 0);
  }
}

import * as THREE from 'three';

export function resolveCircle(pos, radius, colliders) {
  for (let iter = 0; iter < 2; iter++) {
    for (const c of colliders) {
      const nx = Math.max(c.minX, Math.min(pos.x, c.maxX));
      const nz = Math.max(c.minZ, Math.min(pos.z, c.maxZ));
      let dx = pos.x - nx;
      let dz = pos.z - nz;
      const d2 = dx * dx + dz * dz;
      if (d2 >= radius * radius) continue;
      if (d2 > 1e-8) {
        const d = Math.sqrt(d2);
        const push = radius - d;
        pos.x += (dx / d) * push;
        pos.z += (dz / d) * push;
      } else {
        // inside the box — push out along the nearest face
        const left = pos.x - c.minX;
        const right = c.maxX - pos.x;
        const back = pos.z - c.minZ;
        const front = c.maxZ - pos.z;
        const m = Math.min(left, right, back, front);
        if (m === left) pos.x = c.minX - radius;
        else if (m === right) pos.x = c.maxX + radius;
        else if (m === back) pos.z = c.minZ - radius;
        else pos.z = c.maxZ + radius;
      }
    }
  }
}

const _ray = new THREE.Raycaster();
const _from = new THREE.Vector3();
const _to = new THREE.Vector3();

export function lineBlocked(from, to, occluders, margin = 0.15) {
  _from.copy(from);
  _to.copy(to);
  _ray.set(_from, _to.clone().sub(_from).normalize());
  _ray.far = _from.distanceTo(_to) - margin;
  _ray.near = 0.05;
  const hits = _ray.intersectObjects(occluders, false);
  return hits.length > 0;
}

export function randomPointInCircle(radius) {
  const a = Math.random() * Math.PI * 2;
  const r = Math.sqrt(Math.random()) * radius;
  return { x: Math.cos(a) * r, z: Math.sin(a) * r };
}

import * as THREE from 'three';
import { resolveCircle, lineBlocked } from './physics.js';
import { audio } from './audio.js';

const _v = new THREE.Vector3();
const _v2 = new THREE.Vector3();
const _v3 = new THREE.Vector3();

function rand(a, b) { return a + Math.random() * (b - a); }

class Enemy {
  constructor(scene, world, effects, spawn, boss = false) {
    this.scene = scene;
    this.world = world;
    this.effects = effects;
    this.boss = boss;
    this.scale = boss ? 1.33 : rand(0.95, 1.04);
    this.maxHealth = boss ? 620 : 100;
    this.health = this.maxHealth;
    this.speed = boss ? 1.45 : rand(1.85, 2.35);
    this.state = 'spawn';
    this.spawnTimer = 0.7;
    this.deadTimer = 0;
    this.radius = 0.4 * this.scale;
    this.losTimer = 0;
    this.los = false;
    this.fireCooldown = rand(0.9, 2.2);
    this.burstLeft = 0;
    this.shotDelay = 0;
    this.walkPhase = Math.random() * 10;
    this.strafeSign = Math.random() > 0.5 ? 1 : -1;
    this.strafeTimer = rand(1.2, 2.8);
    this.flash = 0;
    this.deathSide = Math.random() > 0.5 ? 1 : -1;
    this.remove = false;
    this.target = new THREE.Vector3(spawn.x, 0, spawn.z);
    this.position = new THREE.Vector3(spawn.x, 0, spawn.z);
    this.killedByHeadshot = false;
    this.lastHitPart = 'body';
    this.gunKick = 0;
    this.aimTime = 0;

    this.build();
    this.root.position.copy(this.position);
    this.root.scale.setScalar(0.001);
    scene.add(this.root);

    this.buildHealthBar();
    this.healthBar.visible = false;
    this.effects.spawnRing(this.position, boss ? 0xffb143 : 0xff4930, boss ? 1.8 : 1);
    this.spawnLight = new THREE.PointLight(boss ? 0xffa53a : 0xff3a22, boss ? 18 : 8, 6, 2);
    this.spawnLight.position.set(spawn.x, 1.1, spawn.z);
    scene.add(this.spawnLight);
  }

  build() {
    const boss = this.boss;
    const armor = new THREE.MeshStandardMaterial({ color: boss ? 0x42321d : 0x20282c, roughness: 0.62, metalness: 0.42, emissive: 0x000000, envMapIntensity: 0.6 });
    const armorDark = new THREE.MeshStandardMaterial({ color: boss ? 0x2a2216 : 0x11171a, roughness: 0.76, metalness: 0.24, emissive: 0x000000 });
    const cloth = new THREE.MeshStandardMaterial({ color: 0x111619, roughness: 0.92, metalness: 0.06, emissive: 0x000000 });
    const accent = new THREE.MeshStandardMaterial({ color: boss ? 0xffb03a : 0xc43226, emissive: boss ? 0xff8a10 : 0x6d0d08, emissiveIntensity: 1.25, roughness: 0.44, metalness: 0.5 });
    const visor = new THREE.MeshBasicMaterial({ color: boss ? 0xffc24a : 0xff3024, toneMapped: false });
    const gunMetal = new THREE.MeshStandardMaterial({ color: 0x0e1214, roughness: 0.5, metalness: 0.85 });
    this.flashMats = [armor, armorDark, cloth];
    this.accentMat = accent;

    this.root = new THREE.Group();
    this.body = new THREE.Group();
    this.root.add(this.body);

    const mesh = (geo, mat, x, y, z, parent = this.body) => {
      const m = new THREE.Mesh(geo, mat);
      m.position.set(x, y, z);
      m.castShadow = true;
      m.receiveShadow = true;
      parent.add(m);
      return m;
    };

    // hips / torso
    mesh(new THREE.BoxGeometry(0.34, 0.24, 0.25), armorDark, 0, 0.92, 0);
    this.torso = mesh(new THREE.BoxGeometry(0.48, 0.52, 0.30), armor, 0, 1.23, 0);
    this.torso.userData.part = 'body';
    mesh(new THREE.BoxGeometry(0.51, 0.2, 0.34), armorDark, 0, 1.45, 0.01);
    mesh(new THREE.BoxGeometry(0.24, 0.12, 0.04), accent, 0, 1.31, 0.17);
    mesh(new THREE.BoxGeometry(0.06, 0.19, 0.03), accent, -0.15, 1.23, 0.165);
    mesh(new THREE.BoxGeometry(0.06, 0.19, 0.03), accent, 0.15, 1.23, 0.165);
    mesh(new THREE.BoxGeometry(0.37, 0.16, 0.23), armorDark, 0, 1.04, 0.02);
    for (let i = 0; i < 3; i++) mesh(new THREE.BoxGeometry(0.10, 0.12, 0.06), armorDark, -0.12 + i * 0.12, 1.10, 0.17);

    // backpack
    mesh(new THREE.BoxGeometry(0.36, 0.40, 0.17), armorDark, 0, 1.30, -0.22);
    mesh(new THREE.BoxGeometry(0.28, 0.08, 0.04), accent, 0, 1.38, -0.315);
    if (boss) {
      mesh(new THREE.CylinderGeometry(0.07, 0.07, 0.34, 8), armorDark, -0.25, 1.45, -0.26);
      mesh(new THREE.CylinderGeometry(0.07, 0.07, 0.34, 8), armorDark, 0.25, 1.45, -0.26);
    }

    // head
    this.headGroup = new THREE.Group();
    this.headGroup.position.set(0, 1.63, 0);
    this.body.add(this.headGroup);
    mesh(new THREE.CylinderGeometry(0.085, 0.11, 0.15, 8), cloth, 0, 0.02, 0, this.headGroup);
    this.head = mesh(new THREE.SphereGeometry(0.175, 16, 12), armor, 0, 0.17, 0, this.headGroup);
    this.head.scale.set(0.94, 1.05, 1);
    this.head.userData.part = 'head';
    mesh(new THREE.BoxGeometry(0.34, 0.14, 0.32), armorDark, 0, 0.285, -0.015, this.headGroup);
    mesh(new THREE.BoxGeometry(0.38, 0.06, 0.36), boss ? armor : armorDark, 0, 0.355, -0.02, this.headGroup);
    const visor = mesh(new THREE.BoxGeometry(0.26, 0.064, 0.03), visor, 0, 0.19, 0.165, this.headGroup);
    visor.userData.part = 'head';
    mesh(new THREE.BoxGeometry(0.07, 0.14, 0.17), armorDark, 0.18, 0.20, 0.02, this.headGroup);
    mesh(new THREE.BoxGeometry(0.05, 0.15, 0.05), accent, 0.20, 0.29, 0.0, this.headGroup);

    // shoulders / arms
    this.armL = new THREE.Group();
    this.armL.position.set(-0.31, 1.42, 0);
    this.body.add(this.armL);
    this.armR = new THREE.Group();
    this.armR.position.set(0.31, 1.42, 0);
    this.body.add(this.armR);
    for (const [arm, side] of [[this.armL, -1], [this.armR, 1]]) {
      mesh(new THREE.SphereGeometry(0.13, 8, 6), armorDark, side * 0.01, 0.0, 0, arm);
      mesh(new THREE.BoxGeometry(0.15, 0.30, 0.16), armor, 0, -0.19, 0, arm);
      mesh(new THREE.BoxGeometry(0.13, 0.26, 0.14), armorDark, 0, -0.43, 0.02, arm);
      mesh(new THREE.BoxGeometry(0.11, 0.10, 0.12), cloth, 0, -0.58, 0.03, arm);
      mesh(new THREE.BoxGeometry(0.15, 0.07, 0.17), armorDark, 0, -0.23, 0.0, arm);
      const hand = mesh(new THREE.BoxGeometry(0.13, 0.10, 0.14), cloth, 0, -0.60, 0.04, arm);
      if (side > 0) this.rightHand = hand;
    }
    this.armR.rotation.x = -0.72;
    this.armL.rotation.x = -1.17;
    this.armL.rotation.z = -0.2;
    this.armR.rotation.z = 0.12;

    // legs
    this.legL = new THREE.Group();
    this.legL.position.set(-0.15, 0.88, 0);
    this.body.add(this.legL);
    this.legR = new THREE.Group();
    this.legR.position.set(0.15, 0.88, 0);
    this.body.add(this.legR);
    for (const [leg, side] of [[this.legL, -1], [this.legR, 1]]) {
      mesh(new THREE.BoxGeometry(0.17, 0.40, 0.19), armorDark, 0, -0.20, 0, leg);
      mesh(new THREE.BoxGeometry(0.145, 0.37, 0.16), armor, 0, -0.57, 0.01, leg);
      mesh(new THREE.BoxGeometry(0.19, 0.14, 0.30), armorDark, 0, -0.79, 0.05, leg);
      mesh(new THREE.BoxGeometry(0.16, 0.045, 0.21), accent, side * 0.0, -0.46, 0.08, leg);
    }

    // weapon
    this.gun = new THREE.Group();
    this.gun.position.set(0.11, 1.12, 0.27);
    this.gun.rotation.x = -0.06;
    this.body.add(this.gun);
    mesh(new THREE.BoxGeometry(0.10, 0.12, 0.58), gunMetal, 0, 0, 0, this.gun);
    mesh(new THREE.BoxGeometry(0.06, 0.06, 0.36), gunMetal, 0, 0.02, 0.43, this.gun);
    mesh(new THREE.CylinderGeometry(0.022, 0.022, 0.30, 8), gunMetal, 0, 0.025, 0.70, this.gun).rotation.x = Math.PI / 2;
    mesh(new THREE.BoxGeometry(0.055, 0.15, 0.12), gunMetal, 0, -0.11, 0.04, this.gun);
    mesh(new THREE.BoxGeometry(0.05, 0.06, 0.14), accent, 0, 0.075, -0.03, this.gun);
    this.gunTip = new THREE.Object3D();
    this.gunTip.position.set(0, 0.025, 0.86);
    this.gun.add(this.gunTip);

    this.root.scale.setScalar(this.scale);
  }

  buildHealthBar() {
    this.healthBar = new THREE.Group();
    const bg = new THREE.Mesh(new THREE.PlaneGeometry(0.62, 0.07), new THREE.MeshBasicMaterial({ color: 0x040708, transparent: true, opacity: 0.72, depthWrite: false, depthTest: true }));
    const fill = new THREE.Mesh(new THREE.PlaneGeometry(0.57, 0.032), new THREE.MeshBasicMaterial({ color: this.boss ? 0xffb04a : 0xff4c3a, toneMapped: false, depthWrite: false, depthTest: true }));
    fill.position.z = 0.001;
    this.healthBar.add(bg, fill);
    this.healthFill = fill;
    this.healthBar.visible = false;
    this.scene.add(this.healthBar);
  }

  get eye() {
    return _v.set(this.position.x, 1.68 * this.scale, this.position.z);
  }

  damage(amount, part, hitPoint, direction) {
    if (this.state === 'dead') return { killed: false, headshot: false };
    const headshot = part === 'head';
    this.health -= amount;
    this.flash = 0.18;
    this.lastHitPart = part;
    if (hitPoint) this.effects.impact(hitPoint, direction ? direction.clone().negate() : new THREE.Vector3(0, 1, 0), 'blood');
    audio.hit(headshot);
    if (this.health <= 0) {
      this.die(headshot);
      return { killed: true, headshot };
    }
    return { killed: false, headshot };
  }

  die(headshot) {
    this.state = 'dead';
    this.killedByHeadshot = headshot;
    this.deadTimer = 0;
    this.healthBar.visible = false;
    this.deathSide = Math.random() > 0.5 ? 1 : -1;
    this.effects.deathBurst(this.position, this.boss ? 0xffb03a : 0xff3a26, this.boss ? 1.8 : 1);
    if (this.boss) {
      this.effects.explode(this.position.clone().setY(1.1), 0xff8a35, 1.5);
    }
    this.spawnLight.intensity = 0;
  }

  update(dt, time, player, camera, manager) {
    if (this.remove) return;
    if (this.state === 'dead') {
      this.deadTimer += dt;
      const t = Math.min(1, this.deadTimer / 0.45);
      this.root.rotation.z = this.deathSide * t * 1.48;
      this.root.position.y = -t * 0.12;
      this.healthBar.visible = false;
      if (this.deadTimer > 3.2) {
        this.root.visible = false;
        this.healthBar.visible = false;
        this.remove = true;
      }
      return;
    }

    if (this.spawnTimer > 0) {
      this.spawnTimer -= dt;
      const t = Math.max(0, 1 - this.spawnTimer / 0.7);
      this.root.scale.setScalar(this.scale * (0.001 + t * t * (3 - 2 * t)));
      if (this.spawnLight) this.spawnLight.intensity = (1 - t) * (this.boss ? 20 : 9);
      if (this.spawnTimer <= 0) {
        this.root.scale.setScalar(this.scale);
        this.state = 'active';
        this.spawnLight.intensity = 0;
        this.scene.remove(this.spawnLight);
        this.spawnLight = null;
      }
      return;
    }

    if (this.flash > 0) this.flash -= dt;
    const flash = Math.max(0, this.flash / 0.18);
    for (const m of this.flashMats) m.emissive.setRGB(flash * 0.55, flash * 0.12, flash * 0.04);

    const playerEye = _v2.set(player.position.x, player.position.y, player.position.z);
    this.losTimer -= dt;
    if (this.losTimer <= 0) {
      this.losTimer = 0.22;
      const eye = new THREE.Vector3(this.position.x, 1.7 * this.scale, this.position.z);
      this.los = !lineBlocked(eye, playerEye, this.world.occluders);
    }

    const dx = player.position.x - this.position.x;
    const dz = player.position.z - this.position.z;
    const dist = Math.hypot(dx, dz);
    const dirX = dist > 0.001 ? dx / dist : 0;
    const dirZ = dist > 0.001 ? dz / dist : 1;

    // face player
    const targetYaw = Math.atan2(dirX, dirZ);
    let yawDiff = targetYaw - this.root.rotation.y;
    while (yawDiff > Math.PI) yawDiff -= Math.PI * 2;
    while (yawDiff < -Math.PI) yawDiff += Math.PI * 2;
    this.root.rotation.y += yawDiff * Math.min(1, dt * 8);

    // move
    let moveX = 0;
    let moveZ = 0;
    this.strafeTimer -= dt;
    if (this.strafeTimer <= 0) {
      this.strafeTimer = rand(1.4, 2.8);
      this.strafeSign *= -1;
    }
    const preferred = this.boss ? 8 : 9.5;
    if (!this.los || dist > preferred + 3) {
      moveX += dirX;
      moveZ += dirZ;
    } else if (dist < preferred - 3.5) {
      moveX -= dirX;
      moveZ -= dirZ;
    } else {
      moveX += -dirZ * this.strafeSign * 0.72;
      moveZ += dirX * this.strafeSign * 0.72;
    }
    // separations from other agents
    for (const other of manager.enemies) {
      if (other === this || other.state === 'dead') continue;
      const ox = this.position.x - other.position.x;
      const oz = this.position.z - other.position.z;
      const d2 = ox * ox + oz * oz;
      if (d2 > 0.001 && d2 < 1.1) {
        const d = Math.sqrt(d2);
        moveX += (ox / d) * (1 - d / 1.05) * 1.6;
        moveZ += (oz / d) * (1 - d / 1.05) * 1.6;
      }
    }
    const moveLen = Math.hypot(moveX, moveZ);
    if (moveLen > 0.001) {
      moveX /= moveLen;
      moveZ /= moveLen;
      const sprintFactor = this.los ? 0.78 : 1;
      this.position.x += moveX * this.speed * dt * sprintFactor;
      this.position.z += moveZ * this.speed * dt * sprintFactor;
      resolveCircle(this.position, this.radius, this.world.colliders);
      this.walkPhase += dt * (this.los ? 6.2 : 8.2);
      const swing = Math.sin(this.walkPhase) * 0.42;
      this.legL.rotation.x = swing;
      this.legR.rotation.x = -swing;
      this.body.position.y = Math.abs(Math.sin(this.walkPhase)) * 0.035;
      this.body.rotation.z = Math.sin(this.walkPhase) * 0.018;
    } else {
      this.walkPhase += dt * 1.2;
      this.legL.rotation.x += (0 - this.legL.rotation.x) * Math.min(1, dt * 7);
      this.legR.rotation.x += (0 - this.legR.rotation.x) * Math.min(1, dt * 7);
      this.body.position.y += (0 - this.body.position.y) * Math.min(1, dt * 8);
      this.body.rotation.z += (0 - this.body.rotation.z) * Math.min(1, dt * 8);
    }

    this.root.position.x = this.position.x;
    this.root.position.z = this.position.z;

    // combat
    this.fireCooldown -= dt;
    this.aimTime += dt;
    if (this.los && dist < 40 && this.fireCooldown <= 0 && this.burstLeft <= 0) {
      this.burstLeft = this.boss ? 6 : 3;
      this.shotDelay = 0.22;
      this.fireCooldown = this.boss ? rand(1.5, 2.1) : rand(1.7, 2.8);
    }
    if (this.burstLeft > 0) {
      this.shotDelay -= dt;
      if (this.shotDelay <= 0) {
        this.shotDelay = this.boss ? 0.095 : 0.14;
        this.burstLeft--;
        this.shoot(player, camera, dist, manager);
      }
    }

    this.gunKick = Math.max(0, this.gunKick - dt * 7);
    this.gun.position.z = 0.27 + this.gunKick * 0.06;
    this.armR.rotation.x = -0.72 + this.gunKick * 0.08;

    // health bar
    const healthRatio = Math.max(0, this.health / this.maxHealth);
    this.healthBar.visible = healthRatio < 0.999;
    if (this.healthBar.visible) {
      this.healthBar.position.set(this.position.x, 2.18 * this.scale, this.position.z);
      this.healthBar.quaternion.copy(camera.quaternion);
      this.healthFill.scale.x = Math.max(0.01, healthRatio);
      this.healthFill.position.x = -(1 - healthRatio) * 0.57 * 0.5;
      this.healthFill.material.color.setHex(healthRatio < 0.35 ? 0xff2f22 : (this.boss ? 0xffa43a : 0xff6a3a));
    }
  }

  shoot(player, camera, dist, manager) {
    const muzzle = new THREE.Vector3();
    this.gunTip.getWorldPosition(muzzle);
    const target = new THREE.Vector3(player.position.x, player.position.y - 0.12, player.position.z);
    const accuracy = this.boss ? 0.52 : Math.max(0.12, 0.47 - dist * 0.008 - (player.sprinting ? 0.08 : 0));
    const hit = Math.random() < accuracy;
    const missOffset = new THREE.Vector3(rand(-1.6, 1.6), rand(-0.7, 1.5), rand(-1.6, 1.6));
    const end = hit ? target : target.clone().add(missOffset);
    this.effects.tracer(muzzle, end, 0xff6d3a, 0.075);
    this.effects.spriteAt(muzzle, 0.55, 0.06, 0xff9b52, 'muzzle');
    this.gunKick = 1;
    const pan = THREE.MathUtils.clamp((this.position.x - player.position.x) / 30, -0.8, 0.8);
    audio.enemyShot(dist, pan);
    if (hit) manager.onPlayerHit(this.boss ? rand(9, 14) : rand(4.5, 8), this);
  }
}

export class EnemyManager {
  constructor(scene, world, effects, callbacks) {
    this.scene = scene;
    this.world = world;
    this.effects = effects;
    this.callbacks = callbacks;
    this.enemies = [];
    this.spawnLightPool = [];
  }

  spawn(spawn, boss = false) {
    const enemy = new Enemy(this.scene, this.world, this.effects, spawn, boss);
    this.enemies.push(enemy);
    return enemy;
  }

  get alive() {
    return this.enemies.filter(e => !e.remove && e.state !== 'dead').length;
  }

  get targets() {
    const arr = [];
    for (const e of this.enemies) {
      if (e.remove || e.state === 'dead') continue;
      if (e.torso) arr.push(e.torso);
      if (e.head) arr.push(e.head);
    }
    return arr;
  }

  update(dt, time, player, camera) {
    for (const enemy of this.enemies) enemy.update(dt, time, player, camera, this);
    for (let i = this.enemies.length - 1; i >= 0; i--) {
      const e = this.enemies[i];
      if (e.remove) {
        this.scene.remove(e.root);
        this.scene.remove(e.healthBar);
        if (e.spawnLight) this.scene.remove(e.spawnLight);
        this.enemies.splice(i, 1);
      }
    }
  }

  clear() {
    for (const e of this.enemies) {
      this.scene.remove(e.root);
      this.scene.remove(e.healthBar);
      if (e.spawnLight) this.scene.remove(e.spawnLight);
    }
    this.enemies.length = 0;
  }

  onPlayerHit(amount, enemy) {
    this.callbacks.onPlayerHit(amount, enemy);
  }
}

