import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
page.setDefaultTimeout(120000);
page.on('console', m => { if (/CONTEXT|error/i.test(m.text())) console.log('CONSOLE', m.type(), m.text().slice(0, 160)); });
const url = process.argv[2] || 'http://localhost:3002';
await page.goto(url, { waitUntil: 'load' });
await page.waitForTimeout(1500);
const mode = process.argv[3] || 'nocss';
if (mode === 'nocss') {
  await page.addStyleTag({ content: `*{animation:none !important; backdrop-filter:none !important; mix-blend-mode:normal !important; filter:none !important;} #screen-fx{display:none !important;}` });
}
if (!process.argv.includes('nostart')) {
  await page.getByRole('button', { name: 'START GAME', exact: true }).first().click({ noWaitAfter: true });
}
for (let i = 0; i < 4; i++) {
  await page.waitForTimeout(2000);
  const d = await page.evaluate(() => ({ f: window.__blacksite?.frames, state: window.__blacksite?.G.state, lost: window.__blacksite?.renderer.getContext().isContextLost(), calls: window.__blacksite?.renderer.info.render.calls }));
  console.log(i, JSON.stringify(d));
  if (d.lost) break;
}
await browser.close();

