import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
page.setDefaultTimeout(120000);
page.on('pageerror', e => console.log('PAGEERROR', (e.stack || e.message).slice(0, 400)));
page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE', m.text().slice(0, 160)); });
await page.goto(process.argv[2] || 'http://localhost:3002', { waitUntil: 'load' });
await page.waitForTimeout(2600);
if (!process.argv.includes('nostart')) await page.getByRole('button', { name: 'START GAME', exact: true }).first().click({ noWaitAfter: true });
await page.waitForTimeout(Number(process.argv[5] || 4200));
await page.evaluate(() => {
  const b = window.__blacksite;
  b.P.pitch = -0.02;
  b.P.yaw = 0;
  b.updateCamera?.(0);
});
await page.waitForTimeout(250);
await page.screenshot({ path: process.argv[3] || '/tmp/opencode/shots/look.jpg', type: 'jpeg', quality: 82, timeout: 60000 });
const data = await page.evaluate(() => {
  const b = window.__blacksite;
  return { state: b.G.state, health: b.G.health, wave: b.G.wave, alive: b.manager.alive, ammo: b.weapon.ammo, frames: b.frames, lost: b.renderer.getContext().isContextLost(), calls: b.renderer.info.render.calls, tris: b.renderer.info.render.triangles, enemies: b.manager.enemies.filter(e => e.state !== 'dead').map(e => [Math.round(e.position.x), Math.round(e.position.z)]) };
});
console.log(JSON.stringify(data));
await browser.close();

