import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'));
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
page.setDefaultTimeout(120000);
page.on('pageerror', e => console.log('PAGEERROR', (e.stack || e.message).slice(0, 500)));
page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE', m.text().slice(0, 160)); });
await page.goto(process.argv[2] || 'http://localhost:3002', { waitUntil: 'load' });
await page.waitForTimeout(2600);
await page.getByRole('button', { name: 'START GAME', exact: true }).first().click({ noWaitAfter: true });
await page.waitForTimeout(1800);
await page.evaluate(() => {
  const b = window.__blacksite;
  b.manager.clear(); b.G.queue.length = 0; b.G.activeWave = false; b.G.spawnTimer = 99;
  b.P.pos.set(0, 0, 16); b.P.yaw = 0; b.P.pitch = -0.045; b.P.speed = 0;
  const e = b.manager.spawn({ x: 0, z: 6.5 });
  e.spawnTimer = 0; e.state = 'active'; e.root.scale.setScalar(e.scale);
  e.spawnLight.intensity = 0; b.scene.remove(e.spawnLight); e.spawnLight = null;
  e.health = 100;
  b.G.state = 'playing';
  window.__testEnemy = e;
});
await page.waitForTimeout(1200);
await page.screenshot({ path: process.argv[3] || '/tmp/opencode/shots/enemy.jpg', type: 'jpeg', quality: 82, timeout: 60000 });
console.log('pre', JSON.stringify(await page.evaluate(() => ({ health: window.__testEnemy.health, dist: Math.hypot(window.__testEnemy.position.x - window.__blacksite.P.pos.x, window.__testEnemy.position.z - window.__blacksite.P.pos.z), playerHealth: window.__blacksite.G.health }))));
await page.mouse.move(640, 400);
await page.mouse.down();
for (let i = 0; i < 8; i++) {
  await page.waitForTimeout(180);
  await page.evaluate(() => {
    const b = window.__blacksite; const e = window.__testEnemy;
    const dx = e.position.x - b.P.pos.x; const dz = e.position.z - b.P.pos.z;
    b.P.yaw = -Math.atan2(dx, -dz);
    b.P.pitch = Math.atan2(1.25 - b.P.eye, Math.hypot(dx, dz));
  });
}
await page.mouse.up();
await page.waitForTimeout(350);
await page.screenshot({ path: process.argv[4] || '/tmp/opencode/shots/combat.jpg', type: 'jpeg', quality: 82, timeout: 60000 });
console.log('post', JSON.stringify(await page.evaluate(() => {
  const b = window.__blacksite;
  return { enemyHealth: window.__testEnemy.health, enemyState: window.__testEnemy.state, kills: b.G.kills, score: b.G.score, shots: b.G.shots, hits: b.G.hits, playerHealth: b.G.health, feed: document.getElementById('killfeed').innerText, lost: b.renderer.getContext().isContextLost(), frames: b.frames };
})));
await page.waitForTimeout(1200);
console.log('later', JSON.stringify(await page.evaluate(() => ({ alive: window.__blacksite.manager.alive, state: window.__blacksite.manager.enemies[0]?.state, remove: window.__blacksite.manager.enemies[0]?.remove }))));
await browser.close();

